#!/usr/bin/env node
// ===========================================================================
// KobPay installer: kobpay-update.mjs   (supersedes add-score-and-reserve.mjs)
//
// Renamed on purpose: Windows kept every re-download of the old name as
// "(1)", "(2)", so the bare filename still pointed at the FIRST version and
// that is the one that ran. Pick this file by date if in doubt.
//
// Needs 031, 032, 033, 034, 035 applied.
//
//   /api/cron/fx  refreshes EVERY currency, not just the switched-on ones,
//                 then activates the ones that become usable        (035)
//   /admin        currency pipeline + reserve currency mismatch     (034,035)
//   /explorer     what backs KPC and which currency it is in        (031,034)
//   /score        credit score built from the ledger                (032)
//   landing       responsive 320-1440px, invented numbers removed   (033)
//
// THE CRON CHANGE IS THE ONE THAT MATTERS
//
// The old loop refreshed currencies that already had a rate AND were already
// active. A currency with no rate was therefore never refreshed, and
// fx_rate() raises for a switched-off currency, so it could not be turned on
// until it had one. 94 currencies were stuck in that loop since 007. That is
// why a global app was showing "Currencies: 1".
//
// NOTE: this REPLACES ClientDashboard.tsx, admin/page.tsx and the fx route.
// Each is copied to <name>.backup first.
//
// Run from C:\kobpay:   node kobpay-update.mjs
// ===========================================================================

import fs from 'node:fs';
import path from 'node:path';

const root = process.cwd();
if (!fs.existsSync(path.join(root, 'app'))) {
  console.error('Run this from C:\\kobpay (the folder with the app directory in it).');
  process.exit(1);
}

let wrote = 0, skipped = 0;

function write(rel, body, backup) {
  const full = path.join(root, rel);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  if (fs.existsSync(full) && fs.readFileSync(full, 'utf8') === body) {
    console.log('  unchanged  ' + rel); skipped++; return;
  }
  if (backup && fs.existsSync(full)) {
    const bak = full + '.backup';
    if (!fs.existsSync(bak)) {
      fs.copyFileSync(full, bak);
      console.log('  backed up  ' + rel + '.backup');
    }
  }
  fs.writeFileSync(full, body);
  console.log('  written    ' + rel); wrote++;
}

console.log('');
console.log('KobPay update — currency pipeline, reserve FX risk, score, responsive landing');
console.log('');

write("app/explorer/page.tsx", "\"use client\";\n\nimport React, { useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport { ArrowLeft, Activity, ShieldCheck, AlertTriangle, Scale, Landmark, Info } from \"lucide-react\";\nimport { supabase } from \"../lib/supabaseClient\";\n\n// This page used to stream Ethereum mainnet: latest block, miner addresses,\n// 0.0000 ETH transfers, \"Active Nodes 1,245\" and \"Finality: Instant\" — for a\n// Postgres ledger that has no nodes and no blocks. It was a borrowed feed\n// with nothing to do with KobPay.\n//\n// What a stablecoin issuer can honestly show, and what is far more\n// interesting, is its own supply: how much KPC exists, how much is backed,\n// and whether the books reconcile. Those are facts nobody else can publish\n// and they are the thing a customer actually wants to know.\n//\n// public_stats() is anon-callable by design — this page is read by people who\n// have not signed in. It exposes totals only; nothing identifies a customer.\n\ntype Stats = {\n  price_usd: number;\n  holders: number;\n  in_circulation: number;\n  total_supply: number;\n  volume_24h: number;\n  transactions_24h: number;\n  apps: number;\n  merchants: number;\n  currencies_supported: number;\n  savings_book: number;\n  as_of: string;\n};\n\nconst n = (v: unknown) => (typeof v === \"number\" ? v : Number(v ?? 0));\nconst kpc = (v: unknown) =>\n  n(v).toLocaleString(undefined, { maximumFractionDigits: 2 });\n\ntype ReserveAccount = {\n  name: string; kind: string; currency: string;\n  balance: number; usd: number; as_of: string; days_old: number;\n  stale: boolean; unvalued?: boolean;\n};\ntype ReserveInstrument = { name: string; issuer: string; value: number };\ntype ReserveComposition = {\n  currency: string; tier: string; usd_value: number;\n  share_percent: number; cannot_value: boolean;\n};\ntype ReserveHistory = { at: string; account: string; balance: number; previous: number };\ntype Reserve = {\n  owed_to_customers: number;\n  owed_breakdown: { wallets: number; savings: number; escrow: number };\n  backing_total: number;\n  coverage_percent: number | null;\n  accounts: ReserveAccount[];\n  composition: ReserveComposition[];\n  instruments: ReserveInstrument[];\n  history: ReserveHistory[];\n  reconciliations_total: number;\n  first_reconciliation: string | null;\n  assurance_note: string;\n};\n\nexport default function ExplorerPage() {\n  const [stats, setStats] = useState<Stats | null>(null);\n  const [reserve, setReserve] = useState<Reserve | null>(null);\n  const [loading, setLoading] = useState(true);\n\n  useEffect(() => {\n    Promise.all([\n      supabase.rpc(\"public_stats\"),\n      supabase.rpc(\"public_reserve\"),\n    ]).then(([a, b]) => {\n      setStats((a.data as Stats) ?? null);\n      setReserve((b.data as Reserve) ?? null);\n      setLoading(false);\n    });\n  }, []);\n\n  const backed = stats ? n(stats.total_supply) : 0;\n\n  return (\n    <div className=\"min-h-[100dvh] bg-[#0A0E14] text-white font-sans p-5 lg:p-10\">\n      <div className=\"max-w-[1000px] mx-auto\">\n        <div className=\"flex items-center gap-3 lg:gap-4 mb-2\">\n          <Link\n            href=\"/\"\n            className=\"text-[#94A3B8] hover:text-[#22D3EE] p-2.5 lg:p-3 bg-[#111827] rounded-xl border border-[#1F2937]\"\n          >\n            <ArrowLeft size={18} />\n          </Link>\n          <h1 className=\"text-xl lg:text-3xl font-black uppercase tracking-widest flex items-center gap-3\">\n            <Activity className=\"text-[#22D3EE]\" /> The ledger\n          </h1>\n        </div>\n        <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mb-8 ml-1\">\n          Every KPC that exists, and what stands behind it\n        </p>\n\n        {loading ? (\n          <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest py-20 text-center\">\n            Loading...\n          </p>\n        ) : !stats ? (\n          <div className=\"bg-[#111827] border border-[#1F2937] rounded-2xl p-8 text-center\">\n            <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.15em]\">\n              The ledger could not be read just now.\n            </p>\n          </div>\n        ) : (\n          <>\n            {/* The peg is the claim everything else rests on, so it leads. */}\n            <div className=\"bg-[#111827] border border-[#1F2937] rounded-2xl p-6 lg:p-8 mb-5\">\n              <div className=\"flex items-start justify-between flex-wrap gap-4\">\n                <div>\n                  <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1\">\n                    One KPC is worth\n                  </p>\n                  <p className=\"text-4xl lg:text-5xl font-black text-[#FDB813]\">\n                    ${n(stats.price_usd).toFixed(2)}\n                  </p>\n                  <p className=\"text-[10px] font-mono text-[#10B981] uppercase tracking-[0.15em] mt-2 flex items-center gap-1.5\">\n                    <ShieldCheck size={12} /> Fixed by design, not by a market\n                  </p>\n                </div>\n                <div className=\"text-right\">\n                  <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1\">\n                    KPC in existence\n                  </p>\n                  <p className=\"text-2xl lg:text-3xl font-black\">{kpc(stats.total_supply)}</p>\n                  <p className=\"text-[10px] font-mono text-[#4B5563] uppercase tracking-[0.15em] mt-1\">\n                    ${kpc(backed)} of claims\n                  </p>\n                </div>\n              </div>\n            </div>\n\n            <div className=\"grid grid-cols-2 lg:grid-cols-4 gap-3 mb-5\">\n              <Stat label=\"Held by people\" value={kpc(stats.in_circulation)} suffix=\"KPC\" />\n              <Stat label=\"Wallets holding KPC\" value={String(n(stats.holders))} />\n              <Stat label=\"Moved in 24h\" value={kpc(stats.volume_24h)} suffix=\"KPC\" />\n              <Stat label=\"Payments in 24h\" value={String(n(stats.transactions_24h))} />\n            </div>\n\n            <div className=\"grid grid-cols-2 lg:grid-cols-4 gap-3 mb-8\">\n              <Stat label=\"Apps on the rail\" value={String(n(stats.apps))} />\n              <Stat label=\"Businesses\" value={String(n(stats.merchants))} />\n              <Stat label=\"Currencies priced\" value={String(n(stats.currencies_supported))} />\n              <Stat label=\"In savings\" value={kpc(stats.savings_book)} suffix=\"KPC\" />\n            </div>\n\n            {reserve && (\n              <div className=\"mb-8\">\n                <h2 className=\"text-sm font-black uppercase tracking-widest mb-1\">\n                  What backs it\n                </h2>\n                <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] mb-4\">\n                  Every KPC is a claim on KobPay for one dollar. This is what we hold\n                  against those claims.\n                </p>\n\n                {/* Coverage leads and is the only number that can end the\n                    company. Green at 100 or above, red below — no softening. */}\n                <div\n                  className={`rounded-2xl p-6 border mb-3 ${\n                    n(reserve.coverage_percent) >= 100\n                      ? \"bg-[#10B981]/5 border-[#10B981]/30\"\n                      : \"bg-[#EF4444]/10 border-[#EF4444]/40\"\n                  }`}\n                >\n                  <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1\">\n                    Coverage\n                  </p>\n                  <p\n                    className={`text-4xl font-black ${\n                      n(reserve.coverage_percent) >= 100 ? \"text-[#10B981]\" : \"text-[#EF4444]\"\n                    }`}\n                  >\n                    {reserve.coverage_percent == null\n                      ? \"—\"\n                      : `${n(reserve.coverage_percent).toFixed(2)}%`}\n                  </p>\n                  <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] mt-2\">\n                    ${kpc(reserve.backing_total)} held · ${kpc(reserve.owed_to_customers)} owed\n                  </p>\n                </div>\n\n                {/* Which currency the backing is in. Every KPC is a claim\n                    for one US dollar, so backing held in another currency\n                    moves with the exchange rate while the claim does not.\n                    An issuer publishing one total can never show that, and\n                    it is the thing most worth knowing. */}\n                {(reserve.composition ?? []).length > 0 && (\n                  <div className=\"bg-[#111827] border border-[#1F2937] rounded-2xl p-5 mb-3\">\n                    <p className=\"text-[9px] font-mono text-[#FDB813] uppercase tracking-[0.2em] mb-1\">\n                      What it is held in\n                    </p>\n                    <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.12em] mb-3 leading-relaxed\">\n                      KPC is a claim for one US dollar. Backing held in another\n                      currency moves with the exchange rate.\n                    </p>\n                    {(reserve.composition ?? []).map((c, i) => (\n                      <div key={i} className=\"py-2 border-b border-[#1F2937] last:border-0\">\n                        <div className=\"flex justify-between items-baseline gap-3\">\n                          <p className=\"text-[11px] font-bold\">\n                            {c.currency}\n                            <span\n                              className={`ml-2 text-[8px] font-mono uppercase tracking-[0.15em] px-1.5 py-0.5 rounded ${\n                                c.tier === \"matched\"\n                                  ? \"bg-[#10B981]/10 text-[#10B981]\"\n                                  : c.tier === \"hard\"\n                                    ? \"bg-[#22D3EE]/10 text-[#22D3EE]\"\n                                    : \"bg-[#FDB813]/10 text-[#FDB813]\"\n                              }`}\n                            >\n                              {c.tier === \"matched\" ? \"matches the claim\" : c.tier}\n                            </span>\n                          </p>\n                          <p className=\"text-xs font-mono font-bold shrink-0\">\n                            {c.cannot_value ? \"—\" : `${n(c.share_percent).toFixed(1)}%`}\n                          </p>\n                        </div>\n                        <div className=\"mt-1.5 h-1.5 bg-[#1F2937] rounded-full\">\n                          <div\n                            className={`h-1.5 rounded-full ${\n                              c.tier === \"matched\"\n                                ? \"bg-[#10B981]\"\n                                : c.tier === \"hard\"\n                                  ? \"bg-[#22D3EE]\"\n                                  : \"bg-[#FDB813]\"\n                            }`}\n                            style={{ width: `${Math.min(100, n(c.share_percent))}%` }}\n                          />\n                        </div>\n                      </div>\n                    ))}\n                  </div>\n                )}\n\n                {reserve.accounts.length > 0 && (\n                  <div className=\"bg-[#111827] border border-[#1F2937] rounded-2xl p-5 mb-3\">\n                    <p className=\"text-[9px] font-mono text-[#FDB813] uppercase tracking-[0.2em] mb-3\">\n                      Where it is held\n                    </p>\n                    {reserve.accounts.map((a, i) => (\n                      <div key={i} className=\"flex justify-between items-start gap-3 py-2 border-b border-[#1F2937] last:border-0\">\n                        <div>\n                          <p className=\"text-[11px] font-bold flex items-center gap-1.5\">\n                            <Landmark size={11} className=\"text-[#94A3B8]\" />\n                            {a.name}\n                          </p>\n                          <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.12em] mt-0.5\">\n                            {a.kind.replace(/_/g, \" \")} · {a.currency}\n                          </p>\n                        </div>\n                        <div className=\"text-right\">\n                          <p className=\"text-xs font-mono font-bold\">\n                            {a.unvalued ? \"not valued\" : `$${kpc(a.usd)}`}\n                          </p>\n                          {/* A figure nobody has refreshed in six weeks proves\n                              very little, and hiding its age is how a\n                              transparency page becomes marketing. */}\n                          <p className={`text-[9px] font-mono uppercase tracking-[0.12em] ${a.stale ? \"text-[#EF4444]\" : \"text-[#4B5563]\"}`}>\n                            {a.stale ? \"out of date · \" : \"\"}\n                            {n(a.days_old) < 1 ? \"today\" : `${Math.round(n(a.days_old))}d ago`}\n                          </p>\n                        </div>\n                      </div>\n                    ))}\n                    {reserve.instruments.map((inst, i) => (\n                      <div key={`i${i}`} className=\"flex justify-between items-start gap-3 py-2 border-b border-[#1F2937] last:border-0\">\n                        <div>\n                          <p className=\"text-[11px] font-bold\">{inst.name}</p>\n                          <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.12em] mt-0.5\">\n                            held with {inst.issuer}\n                          </p>\n                        </div>\n                        <p className=\"text-xs font-mono font-bold\">${kpc(inst.value)}</p>\n                      </div>\n                    ))}\n                  </div>\n                )}\n\n                {/* The track record. Consistency over time is checkable in a\n                    way a single snapshot is not — and it is the part an\n                    issuer cannot manufacture later. */}\n                {reserve.reconciliations_total > 0 && (\n                  <div className=\"bg-[#111827] border border-[#1F2937] rounded-2xl p-5 mb-3\">\n                    <p className=\"text-[9px] font-mono text-[#FDB813] uppercase tracking-[0.2em] mb-1\">\n                      Checked {reserve.reconciliations_total} times\n                    </p>\n                    <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.12em] mb-3\">\n                      since {reserve.first_reconciliation\n                        ? new Date(reserve.first_reconciliation).toLocaleDateString()\n                        : \"—\"}\n                    </p>\n                    {reserve.history.slice(0, 6).map((h, i) => (\n                      <div key={i} className=\"flex justify-between items-baseline py-1\">\n                        <span className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.1em]\">\n                          {new Date(h.at).toLocaleDateString()} · {h.account}\n                        </span>\n                        <span className=\"text-[10px] font-mono font-bold\">{kpc(h.balance)}</span>\n                      </div>\n                    ))}\n                  </div>\n                )}\n\n                {/* Said plainly. Overstating what these numbers prove is the\n                    exact failure other issuers are known for. */}\n                <div className=\"bg-[#1F2937]/40 border border-[#374151] rounded-2xl p-5 flex gap-3\">\n                  <Info size={16} className=\"text-[#94A3B8] shrink-0 mt-0.5\" />\n                  <div>\n                    <p className=\"text-[11px] font-bold mb-1\">Self-reported, not audited</p>\n                    <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] leading-relaxed\">\n                      {reserve.assurance_note}\n                    </p>\n                  </div>\n                </div>\n              </div>\n            )}\n\n            {/* The honest note. A number nobody can check is marketing; the\n                point of this page is that these can be checked. */}\n            <div className=\"bg-[#1F2937]/40 border border-[#374151] rounded-2xl p-5 flex gap-3\">\n              <Scale size={16} className=\"text-[#94A3B8] shrink-0 mt-0.5\" />\n              <div>\n                <p className=\"text-[11px] font-bold mb-1\">Counted, not estimated</p>\n                <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] leading-relaxed\">\n                  Every figure here is read from the ledger when you load the page.\n                  KobPay runs a double-entry ledger: each payment writes two matching\n                  entries, and no account can go below zero. Last read{\" \"}\n                  {new Date(stats.as_of).toLocaleTimeString()}.\n                </p>\n              </div>\n            </div>\n\n            {n(stats.total_supply) === 0 && (\n              <div className=\"mt-5 bg-[#FDB813]/5 border border-[#FDB813]/30 rounded-2xl p-5 flex gap-3\">\n                <AlertTriangle size={16} className=\"text-[#FDB813] shrink-0 mt-0.5\" />\n                <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] leading-relaxed\">\n                  No KPC has been issued yet. These numbers start moving when the\n                  first deposit settles.\n                </p>\n              </div>\n            )}\n          </>\n        )}\n      </div>\n    </div>\n  );\n}\n\nfunction Stat({ label, value, suffix }: { label: string; value: string; suffix?: string }) {\n  return (\n    <div className=\"bg-[#111827] border border-[#1F2937] rounded-xl p-4\">\n      <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mb-1.5\">\n        {label}\n      </p>\n      <p className=\"text-lg lg:text-xl font-black\">\n        {value}\n        {suffix && <span className=\"text-[10px] font-mono text-[#4B5563] ml-1.5\">{suffix}</span>}\n      </p>\n    </div>\n  );\n}\n", false);

write("app/score/page.tsx", "\"use client\";\n\nimport React, { useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport { ArrowLeft, Gauge, ChevronDown, TrendingUp } from \"lucide-react\";\nimport { supabase } from \"../lib/supabaseClient\";\n\n// The copy lesson from /invest applies here more than anywhere: a score is a\n// judgement about a person, and the page has to read like it is on their side.\n// So the number leads, the one thing that would raise it comes second, and the\n// workings go behind a tap for whoever wants them.\n//\n// What this page must NOT do is imply a bureau score. It is KobPay's own, and\n// saying so plainly costs nothing and is the difference between a useful\n// feature and a misleading one.\n\ntype Component = { name: string; points: number; detail: string };\ntype Score = {\n  score: number;\n  band: string;\n  min: number;\n  max: number;\n  components: Component[];\n  improve: string;\n  as_of: string;\n};\n\nconst BANDS: Record<string, { label: string; color: string; ring: string }> = {\n  excellent: { label: \"Excellent\", color: \"#10B981\", ring: \"#10B981\" },\n  good: { label: \"Good\", color: \"#22D3EE\", ring: \"#22D3EE\" },\n  fair: { label: \"Fair\", color: \"#FDB813\", ring: \"#FDB813\" },\n  building: { label: \"Building\", color: \"#94A3B8\", ring: \"#94A3B8\" },\n  \"needs work\": { label: \"Needs work\", color: \"#EF4444\", ring: \"#EF4444\" },\n};\n\nexport default function ScorePage() {\n  const [data, setData] = useState<Score | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState(\"\");\n  const [showWorkings, setShowWorkings] = useState(false);\n\n  useEffect(() => {\n    supabase.rpc(\"my_credit_score\").then(({ data: d, error: e }) => {\n      if (e) setError(e.message);\n      else setData(d as Score);\n      setLoading(false);\n    });\n  }, []);\n\n  const band = data ? BANDS[data.band] ?? BANDS.building : BANDS.building;\n  // Position on the dial, clamped so a floor or ceiling score still draws.\n  const pct = data\n    ? Math.max(0, Math.min(1, (data.score - data.min) / (data.max - data.min)))\n    : 0;\n\n  return (\n    <div className=\"min-h-[100dvh] bg-[#0A0E14] text-white font-sans p-5 lg:p-10\">\n      <div className=\"max-w-[640px] mx-auto\">\n        <div className=\"flex items-center gap-3 lg:gap-4 mb-8\">\n          <Link\n            href=\"/\"\n            className=\"text-[#94A3B8] hover:text-[#22D3EE] p-2.5 lg:p-3 bg-[#111827] rounded-xl border border-[#1F2937]\"\n          >\n            <ArrowLeft size={18} />\n          </Link>\n          <h1 className=\"text-xl lg:text-3xl font-black uppercase tracking-widest flex items-center gap-3\">\n            <Gauge className=\"text-[#FDB813]\" /> Your score\n          </h1>\n        </div>\n\n        {loading ? (\n          <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest py-20 text-center\">\n            Loading...\n          </p>\n        ) : error || !data ? (\n          <div className=\"bg-[#111827] border border-[#1F2937] rounded-2xl p-8 text-center\">\n            <p className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.15em]\">\n              {error || \"Your score could not be read just now.\"}\n            </p>\n          </div>\n        ) : (\n          <>\n            <div className=\"bg-[#111827] border border-[#1F2937] rounded-2xl p-7 lg:p-9 mb-4 text-center\">\n              <p\n                className=\"text-6xl lg:text-7xl font-black leading-none\"\n                style={{ color: band.color }}\n              >\n                {data.score}\n              </p>\n              <p\n                className=\"text-[11px] font-mono uppercase tracking-[0.25em] mt-3 font-bold\"\n                style={{ color: band.color }}\n              >\n                {band.label}\n              </p>\n\n              <div className=\"mt-6 h-2 bg-[#1F2937] rounded-full relative\">\n                <div\n                  className=\"h-2 rounded-full transition-all duration-700\"\n                  style={{ width: `${pct * 100}%`, backgroundColor: band.ring }}\n                />\n              </div>\n              <div className=\"flex justify-between mt-2\">\n                <span className=\"text-[9px] font-mono text-[#4B5563]\">{data.min}</span>\n                <span className=\"text-[9px] font-mono text-[#4B5563]\">{data.max}</span>\n              </div>\n            </div>\n\n            {/* The single most useful thing we can tell them, given pride of\n                place rather than buried under the breakdown. */}\n            <div className=\"bg-[#FDB813]/5 border border-[#FDB813]/30 rounded-2xl p-5 mb-4 flex gap-3\">\n              <TrendingUp size={18} className=\"text-[#FDB813] shrink-0 mt-0.5\" />\n              <div>\n                <p className=\"text-[9px] font-mono text-[#FDB813] uppercase tracking-[0.2em] mb-1\">\n                  What would raise it\n                </p>\n                <p className=\"text-sm font-bold\">{data.improve}</p>\n              </div>\n            </div>\n\n            <button\n              onClick={() => setShowWorkings((v) => !v)}\n              className=\"w-full bg-[#111827] border border-[#1F2937] rounded-2xl p-4 flex items-center justify-between hover:border-[#22D3EE]/40 transition-colors\"\n            >\n              <span className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.2em]\">\n                How this is worked out\n              </span>\n              <ChevronDown\n                size={16}\n                className={`text-[#94A3B8] transition-transform ${showWorkings ? \"rotate-180\" : \"\"}`}\n              />\n            </button>\n\n            {showWorkings && (\n              <div className=\"mt-3 bg-[#111827] border border-[#1F2937] rounded-2xl p-5\">\n                {data.components.map((c, i) => (\n                  <div\n                    key={i}\n                    className=\"flex justify-between items-start gap-4 py-2.5 border-b border-[#1F2937] last:border-0\"\n                  >\n                    <div>\n                      <p className=\"text-[11px] font-bold\">{c.name}</p>\n                      <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.12em] mt-0.5\">\n                        {c.detail}\n                      </p>\n                    </div>\n                    <p\n                      className={`text-xs font-mono font-bold shrink-0 ${\n                        Number(c.points) > 0\n                          ? \"text-[#10B981]\"\n                          : Number(c.points) < 0\n                            ? \"text-[#EF4444]\"\n                            : \"text-[#4B5563]\"\n                      }`}\n                    >\n                      {Number(c.points) > 0 ? \"+\" : \"\"}\n                      {c.points}\n                    </p>\n                  </div>\n                ))}\n                <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] leading-relaxed mt-4 pt-4 border-t border-[#1F2937]\">\n                  Everyone starts at 500. A new account is not a bad one — there is\n                  simply nothing to go on yet.\n                </p>\n              </div>\n            )}\n\n            {/* Not a bureau score, and saying so is the difference between a\n                useful feature and a misleading one. */}\n            <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.12em] leading-relaxed mt-5 text-center\">\n              This is KobPay&apos;s own score, built from how you use KobPay. It is not\n              a credit bureau rating and is not shared with other lenders. Updated{\" \"}\n              {new Date(data.as_of).toLocaleTimeString()}.\n            </p>\n          </>\n        )}\n      </div>\n    </div>\n  );\n}\n", false);

write("app/admin/page.tsx", "\"use client\";\n\nimport React, { useCallback, useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport {\n  ArrowLeft,\n  Scale,\n  Coins,\n  Activity,\n  ShieldAlert,\n  Vault,\n  UserCheck,\n  Siren,\n  Percent,\n  Check,\n  Loader2,\n  AlertTriangle,\n} from \"lucide-react\";\nimport { supabase } from \"../lib/supabaseClient\";\nimport toast, { Toaster } from \"react-hot-toast\";\n\ntype Dispute = {\n  id: string;\n  reference: string;\n  status: string;\n  amount: number;\n  secured: boolean;\n  reason: string;\n  created_at: string;\n  respond_by: string;\n  resolve_by: string;\n  response_overdue: boolean;\n  decision_overdue: boolean;\n  raised_by: string;\n  raiser_phone: string;\n  against: string | null;\n};\n\ntype Row = Record<string, unknown>;\ntype Disputes = { queue: Dispute[]; pool: Row[] };\ntype Money = {\n  supply: Row[];\n  pools: Row[];\n  savings: Row[];\n  rewards: Row[];\n  drift: { accounts: Row[]; savings: Row[]; circles: Row[]; safe: Row[] };\n};\ntype Ops = { fx: Row[]; jobs: Row[] };\ntype CurrencySummary = {\n  total: number; switched_on: number; can_be_valued: number;\n  can_take_money_in: number; no_rate_yet: number; rate_too_old: number;\n};\ntype CurrencyRow = { code: string; name: string; blocked_by: string };\ntype Currencies = { summary: CurrencySummary; rows: CurrencyRow[] };\ntype Reserve = { health: Row; economics: Row; deployments: Row[] };\ntype FxTier = { matched_usd: number; hard: number; soft: number;\n                matched_percent: number; hard_percent: number; soft_percent: number };\ntype FxBreach = { setting: string; says: string; actual: string; fix: string };\ntype FxRow = { currency: string; tier: string; balance: number; usd_value: number;\n               share_percent: number; cannot_value: boolean };\ntype ReserveFx = {\n  has_reserve: boolean; verdict: string; by_tier?: FxTier; breaches?: FxBreach[];\n  composition?: FxRow[]; coverage_percent?: number; coverage_percent_stressed?: number;\n  buffer_needed_usd?: number; coverage_needed_percent?: number; stress_case?: string;\n};\ntype Rates = { rates: Row[]; yields: Row[]; history: Row[] };\ntype Kyc = { queue: Row[]; tiers: Row[] };\ntype Risk = { queue: Row[]; recent: Row[] };\n\nconst n = (v: unknown) => (typeof v === \"number\" ? v : Number(v ?? 0));\nconst money = (v: unknown) =>\n  n(v).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n\n// The view returns reason as a code. Nobody wants to read 'not_as_described'\n// at 2am while deciding whether to refund somebody.\nconst REASONS: Record<string, string> = {\n  not_received: \"Never arrived\",\n  wrong_amount: \"Wrong amount\",\n  duplicate: \"Charged twice\",\n  unauthorised: \"Didn't authorise it\",\n  not_as_described: \"Not as described\",\n  wrong_recipient: \"Went to the wrong person\",\n  other: \"Other\",\n};\n\nconst since = (iso: string) => {\n  const ms = Date.now() - new Date(iso).getTime();\n  const h = Math.floor(ms / 3600000);\n  if (h < 1) return \"just now\";\n  if (h < 48) return `${h}h ago`;\n  return `${Math.floor(h / 24)}d ago`;\n};\n\nconst until = (iso: string) => {\n  const ms = new Date(iso).getTime() - Date.now();\n  if (ms <= 0) return \"overdue\";\n  const h = Math.floor(ms / 3600000);\n  return h < 48 ? `${h}h left` : `${Math.floor(h / 24)}d left`;\n};\n\nexport default function AdminPage() {\n  const [staff, setStaff] = useState<boolean | null>(null);\n  const [tab, setTab] = useState<\"disputes\" | \"kyc\" | \"risk\" | \"money\" | \"reserve\" | \"rates\" | \"ops\">(\"disputes\");\n  const [disputes, setDisputes] = useState<Disputes | null>(null);\n  const [moneyData, setMoneyData] = useState<Money | null>(null);\n  const [ops, setOps] = useState<Ops | null>(null);\n  const [reserve, setReserve] = useState<Reserve | null>(null);\n  const [reserveFx, setReserveFx] = useState<ReserveFx | null>(null);\n  const [currencies, setCurrencies] = useState<Currencies | null>(null);\n  const [rates, setRates] = useState<Rates | null>(null);\n  const [kyc, setKyc] = useState<Kyc | null>(null);\n  const [risk, setRisk] = useState<Risk | null>(null);\n  const [working, setWorking] = useState<string | null>(null);\n\n  const load = useCallback(async () => {\n    const { data: isStaff } = await supabase.rpc(\"am_i_staff\");\n    setStaff(Boolean(isStaff));\n    if (!isStaff) return;\n\n    const [d, m, o, rv, rfx, rt, ky, rk, cu] = await Promise.all([\n      supabase.rpc(\"admin_disputes\"),\n      supabase.rpc(\"admin_money\"),\n      supabase.rpc(\"admin_ops\"),\n      supabase.rpc(\"admin_reserve\"),\n      supabase.rpc(\"admin_reserve_fx\"),\n      supabase.rpc(\"admin_rates\"),\n      supabase.rpc(\"admin_kyc\"),\n      supabase.rpc(\"admin_risk\"),\n      supabase.rpc(\"admin_currencies\"),\n    ]);\n    if (d.data) setDisputes(d.data as Disputes);\n    if (m.data) setMoneyData(m.data as Money);\n    if (o.data) setOps(o.data as Ops);\n    if (rv.data) setReserve(rv.data as Reserve);\n    if (rfx.data) setReserveFx(rfx.data as ReserveFx);\n    if (rt.data) setRates(rt.data as Rates);\n    if (ky.data) setKyc(ky.data as Kyc);\n    if (rk.data) setRisk(rk.data as Risk);\n    if (cu.data) setCurrencies(cu.data as Currencies);\n  }, []);\n\n  useEffect(() => {\n    load();\n  }, [load]);\n\n  const decideRisk = async (id: string, status: \"cleared\" | \"escalated\") => {\n    const note = window.prompt(\n      status === \"cleared\"\n        ? \"Why is this fine? This is the record if anyone asks later.\"\n        : \"What are you escalating, and to whom?\",\n    );\n    if (!note || !note.trim()) return;\n    setWorking(id);\n    const { error } = await supabase.rpc(\"resolve_risk\", {\n      p_event: id,\n      p_status: status,\n      p_note: note.trim(),\n    });\n    setWorking(null);\n    if (error) {\n      toast.error(error.message.replace(/^.*?:\\s*/, \"\"));\n      return;\n    }\n    toast.success(status === \"cleared\" ? \"Cleared\" : \"Escalated\");\n    load();\n  };\n\n  const decideKyc = async (id: string, decision: \"approved\" | \"more_info\" | \"rejected\") => {\n    let note: string | null = null;\n    if (decision !== \"approved\") {\n      note = window.prompt(\n        decision === \"rejected\"\n          ? \"Why are you rejecting this? They see this.\"\n          : \"What else do you need from them? They see this.\",\n      );\n      if (!note || !note.trim()) return;\n    }\n    setWorking(id);\n    const { error } = await supabase.rpc(\"review_kyc\", {\n      p_submission: id,\n      p_decision: decision,\n      p_note: note?.trim() ?? null,\n    });\n    setWorking(null);\n    if (error) {\n      toast.error(error.message.replace(/^.*?:\\s*/, \"\"));\n      return;\n    }\n    toast.success(decision === \"approved\" ? \"Approved\" : \"Sent back to them\");\n    load();\n  };\n\n  const decide = async (d: Dispute, outcome: \"refund\" | \"reject\" | \"partial\") => {\n    const note = window.prompt(\n      outcome === \"reject\"\n        ? `Why are you rejecting ${d.reference}? The customer sees this.`\n        : `Note for ${d.reference} — the customer sees this.`,\n    );\n    if (!note || !note.trim()) return;\n\n    let amount: number | null = null;\n    if (outcome === \"partial\") {\n      const raw = window.prompt(`How much of the ${money(d.amount)} KPC to return?`);\n      if (!raw) return;\n      amount = Number(raw);\n      if (!Number.isFinite(amount) || amount <= 0 || amount > n(d.amount)) {\n        toast.error(\"That amount isn't within the disputed amount\");\n        return;\n      }\n    }\n\n    setWorking(d.id);\n    const { error } = await supabase.rpc(\"resolve_dispute\", {\n      p_dispute: d.id,\n      p_outcome: outcome,\n      p_note: note.trim(),\n      p_amount: amount,\n    });\n    setWorking(null);\n\n    if (error) {\n      toast.error(error.message.replace(/^.*?:\\s*/, \"\"));\n      return;\n    }\n    toast.success(`${d.reference} ${outcome === \"reject\" ? \"rejected\" : \"refunded\"}`);\n    load();\n  };\n\n  if (staff === null) {\n    return (\n      <Shell>\n        <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-widest py-20 text-center\">\n          Loading...\n        </p>\n      </Shell>\n    );\n  }\n\n  if (!staff) {\n    return (\n      <Shell>\n        <div className=\"bg-[#111827] border border-[#1F2937] rounded-2xl p-8 text-center\">\n          <ShieldAlert size={28} className=\"text-[#94A3B8] mx-auto mb-4\" />\n          <p className=\"text-xs font-mono text-[#94A3B8] uppercase tracking-[0.15em] leading-relaxed\">\n            This page is for KobPay staff.\n            <br />\n            If that should be you, your profile needs a staff role.\n          </p>\n        </div>\n      </Shell>\n    );\n  }\n\n  const driftRows = moneyData\n    ? [\n        ...moneyData.drift.accounts,\n        ...moneyData.drift.savings,\n        ...moneyData.drift.circles,\n        ...moneyData.drift.safe,\n      ]\n    : [];\n\n  return (\n    <Shell>\n      <Toaster position=\"top-center\" />\n\n      <div className=\"flex flex-wrap gap-2 mb-6\">\n        {(\n          [\n            [\"disputes\", \"Disputes\", Scale],\n            [\"kyc\", \"Identity\", UserCheck],\n            [\"risk\", \"Risk\", Siren],\n            [\"money\", \"Money\", Coins],\n            [\"reserve\", \"Reserve\", Vault],\n            [\"rates\", \"Rates\", Percent],\n            [\"ops\", \"Jobs\", Activity],\n          ] as const\n        ).map(([key, label, Icon]) => (\n          <button\n            key={key}\n            onClick={() => setTab(key)}\n            className={`flex-1 min-w-[92px] flex items-center justify-center gap-1.5 py-3 rounded-xl border text-[9px] font-mono uppercase tracking-[0.15em] transition-colors ${\n              tab === key\n                ? \"bg-[#FDB813]/10 border-[#FDB813]/50 text-[#FDB813]\"\n                : \"bg-[#1F2937] border-[#374151] text-[#94A3B8] hover:text-white\"\n            }`}\n          >\n            <Icon size={13} />\n            {label}\n            {key === \"risk\" && risk && risk.queue.length > 0 && (\n              <span className=\"ml-1 px-1.5 py-0.5 rounded bg-[#EF4444] text-white font-black\">\n                {risk.queue.length}\n              </span>\n            )}\n            {key === \"kyc\" && kyc && kyc.queue.length > 0 && (\n              <span className=\"ml-1 px-1.5 py-0.5 rounded bg-[#FDB813] text-[#0A0E14] font-black\">\n                {kyc.queue.length}\n              </span>\n            )}\n            {key === \"disputes\" && disputes && disputes.queue.length > 0 && (\n              <span className=\"ml-1 px-1.5 py-0.5 rounded bg-[#FDB813] text-[#0A0E14] font-black\">\n                {disputes.queue.length}\n              </span>\n            )}\n          </button>\n        ))}\n      </div>\n\n      {/* The single most important thing on this page: if any drift view has a\n          row, the ledger and the balances disagree and nothing else matters. */}\n      {driftRows.length > 0 && (\n        <div className=\"mb-6 bg-[#EF4444]/10 border border-[#EF4444]/40 rounded-xl p-4 flex items-start gap-3\">\n          <AlertTriangle size={18} className=\"text-[#EF4444] shrink-0 mt-0.5\" />\n          <div>\n            <p className=\"text-[10px] font-mono text-[#EF4444] uppercase tracking-[0.15em] font-bold\">\n              {driftRows.length} account{driftRows.length === 1 ? \"\" : \"s\"} out of balance\n            </p>\n            <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] mt-1 leading-relaxed\">\n              The ledger and the stored balances disagree. Stop and investigate before\n              approving anything.\n            </p>\n          </div>\n        </div>\n      )}\n\n      {tab === \"disputes\" && disputes && (\n        <>\n          {disputes.pool.map((p, i) => (\n            <div key={i} className=\"mb-5 grid grid-cols-2 gap-2\">\n              <Stat label=\"Dispute pool\" value={`${money(p.pool)} KPC`} />\n              <Stat\n                label=\"Float available\"\n                value={`${money(p.float_available)} KPC`}\n                bad={Boolean(p.shortfall) || Boolean(p.float_below_exposure)}\n              />\n            </div>\n          ))}\n\n          {disputes.queue.length === 0 ? (\n            <Empty>Nothing waiting on a decision</Empty>\n          ) : (\n            <div className=\"space-y-3\">\n              {disputes.queue.map((d) => (\n                <div\n                  key={d.id}\n                  className={`bg-[#111827] border rounded-xl p-4 ${\n                    d.decision_overdue\n                      ? \"border-[#EF4444]/50\"\n                      : d.response_overdue\n                        ? \"border-[#FDB813]/40\"\n                        : \"border-[#1F2937]\"\n                  }`}\n                >\n                  <div className=\"flex justify-between items-start mb-3\">\n                    <div>\n                      <p className=\"text-sm font-black\">{money(d.amount)} KPC</p>\n                      <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mt-0.5\">\n                        {REASONS[d.reason] ?? d.reason} · {d.reference}\n                      </p>\n                    </div>\n                    <span\n                      className={`text-[9px] font-mono uppercase tracking-[0.15em] px-2 py-1 rounded ${\n                        d.decision_overdue\n                          ? \"bg-[#EF4444]/15 text-[#EF4444]\"\n                          : \"bg-[#1F2937] text-[#94A3B8]\"\n                      }`}\n                    >\n                      {until(d.resolve_by)}\n                    </span>\n                  </div>\n\n                  <div className=\"text-[10px] font-mono text-[#94A3B8] leading-relaxed mb-3\">\n                    <span className=\"text-white\">{d.raised_by}</span> ({d.raiser_phone})\n                    {d.against && (\n                      <>\n                        {\" \"}\n                        against <span className=\"text-white\">{d.against}</span>\n                      </>\n                    )}\n                    <br />\n                    Raised {since(d.created_at)} ·{\" \"}\n                    {d.secured ? \"money is held\" : \"money already left\"} ·{\" \"}\n                    {d.status === \"answered\" ? \"they replied\" : \"no reply yet\"}\n                  </div>\n\n                  <div className=\"grid grid-cols-3 gap-2\">\n                    <Act\n                      onClick={() => decide(d, \"refund\")}\n                      busy={working === d.id}\n                      tone=\"good\"\n                    >\n                      Refund all\n                    </Act>\n                    <Act onClick={() => decide(d, \"partial\")} busy={working === d.id}>\n                      Part\n                    </Act>\n                    <Act onClick={() => decide(d, \"reject\")} busy={working === d.id} tone=\"bad\">\n                      Reject\n                    </Act>\n                  </div>\n                </div>\n              ))}\n            </div>\n          )}\n        </>\n      )}\n\n      {tab === \"money\" && moneyData && (\n        <div className=\"space-y-5\">\n          {moneyData.supply.map((s, i) => (\n            <Panel key={i} title=\"KPC in existence\">\n              <KV k=\"Issued\" v={`${money(s.issued)} KPC`} />\n              <KV k=\"Redeemed\" v={`${money(s.redeemed)} KPC`} />\n              <KV k=\"In customer hands\" v={`${money(s.in_customer_hands)} KPC`} />\n              <KV k=\"In pools\" v={`${money(s.held_in_pools)} KPC`} />\n              <KV k=\"In escrow\" v={`${money(s.in_escrow)} KPC`} />\n              <KV\n                k=\"Unexplained\"\n                v={`${money(s.unexplained)} KPC`}\n                bad={n(s.unexplained) !== 0}\n              />\n            </Panel>\n          ))}\n\n          <Panel title=\"Pools\">\n            {moneyData.pools.map((p, i) => (\n              <KV key={i} k={String(p.label ?? p.ref)} v={`${money(p.balance)} KPC`} />\n            ))}\n          </Panel>\n\n          {moneyData.savings.map((s, i) => (\n            <Panel key={i} title=\"Savings\">\n              <KV k=\"Customer principal\" v={`${money(s.customer_principal)} KPC`} />\n              <KV k=\"Interest accrued, unpaid\" v={`${money(s.interest_accrued_unpaid)} KPC`} />\n              <KV k=\"Interest overdue\" v={`${money(s.interest_overdue)} KPC`} bad={n(s.interest_overdue) > 0} />\n              <KV k=\"Costs per day\" v={`${money(s.daily_interest_cost)} KPC`} />\n              <KV\n                k=\"Pool surplus\"\n                v={`${money(s.pool_surplus_or_shortfall)} KPC`}\n                bad={n(s.pool_surplus_or_shortfall) < 0}\n              />\n            </Panel>\n          ))}\n\n          {moneyData.rewards.map((r, i) => (\n            <Panel key={i} title=\"Rewards\">\n              <KV k=\"Points outstanding\" v={String(r.points_outstanding ?? 0)} />\n              <KV k=\"Owed if all redeemed\" v={`${money(r.owed_if_all_redeemed)} KPC`} />\n              <KV\n                k=\"Pool surplus\"\n                v={`${money(r.surplus_or_shortfall)} KPC`}\n                bad={n(r.surplus_or_shortfall) < 0}\n              />\n            </Panel>\n          ))}\n\n          {driftRows.length === 0 && (\n            <div className=\"flex items-center justify-center gap-2 py-4 text-[9px] font-mono uppercase tracking-[0.15em] text-[#10B981]\">\n              <Check size={13} /> Every balance matches its ledger\n            </div>\n          )}\n        </div>\n      )}\n\n      {tab === \"kyc\" && kyc && (\n        <div className=\"space-y-3\">\n          {kyc.queue.length === 0 ? (\n            <Empty>Nobody waiting to be verified</Empty>\n          ) : (\n            kyc.queue.map((k, i) => (\n              <div key={i} className=\"bg-[#111827] border border-[#1F2937] rounded-xl p-4\">\n                <div className=\"flex justify-between items-start mb-2\">\n                  <div>\n                    <p className=\"text-sm font-bold\">{String(k.full_name)}</p>\n                    <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mt-0.5\">\n                      {String(k.phone)} · {String(k.tier_now)} → {String(k.tier_wanted)}\n                    </p>\n                  </div>\n                  <span className=\"text-[9px] font-mono uppercase tracking-[0.15em] px-2 py-1 rounded bg-[#1F2937] text-[#94A3B8]\">\n                    {n(k.hours_waiting) < 1 ? \"just now\" : `${Math.round(n(k.hours_waiting))}h`}\n                  </span>\n                </div>\n\n                <div className=\"bg-[#0A0E14] border border-[#1F2937] rounded-lg p-3 mb-3 space-y-1\">\n                  <KV k=\"ID\" v={`${String(k.id_type).replace(/_/g, \" \")} · ${String(k.id_reference ?? \"—\")}`} />\n                  {k.address ? <KV k=\"Address\" v={String(k.address)} /> : null}\n                  {/* Blank is normal — it is optional on the form and asked\n                      for with 'More info' only when the amounts warrant it. */}\n                  <KV k=\"Source of funds\" v={String(k.source_of_funds ?? \"not given\")} />\n                </div>\n\n                <div className=\"grid grid-cols-3 gap-2\">\n                  <Act onClick={() => decideKyc(String(k.id), \"approved\")} busy={working === k.id} tone=\"good\">\n                    Approve\n                  </Act>\n                  <Act onClick={() => decideKyc(String(k.id), \"more_info\")} busy={working === k.id}>\n                    More info\n                  </Act>\n                  <Act onClick={() => decideKyc(String(k.id), \"rejected\")} busy={working === k.id} tone=\"bad\">\n                    Reject\n                  </Act>\n                </div>\n              </div>\n            ))\n          )}\n\n          <Panel title=\"Who is on what\">\n            {kyc.tiers.map((t, i) => (\n              <KV\n                key={i}\n                k={`${String(t.name)} · ${kpcShort(t.daily_kpc)}/day`}\n                v={`${n(t.people)} ${n(t.people) === 1 ? \"person\" : \"people\"}`}\n              />\n            ))}\n          </Panel>\n        </div>\n      )}\n\n      {tab === \"risk\" && risk && (\n        <div className=\"space-y-3\">\n          {risk.queue.length === 0 ? (\n            <Empty>Nothing flagged</Empty>\n          ) : (\n            risk.queue.map((r, i) => (\n              <div\n                key={i}\n                className={`bg-[#111827] border rounded-xl p-4 ${\n                  r.severity === \"high\" ? \"border-[#EF4444]/50\" : \"border-[#1F2937]\"\n                }`}\n              >\n                <div className=\"flex justify-between items-start mb-2\">\n                  <div>\n                    <p className=\"text-sm font-bold capitalize\">\n                      {String(r.kind).replace(/_/g, \" \")}\n                    </p>\n                    <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mt-0.5\">\n                      {String(r.full_name ?? \"unknown\")} · {String(r.phone ?? \"—\")} ·{\" \"}\n                      {String(r.kyc_tier ?? \"—\")}\n                    </p>\n                  </div>\n                  <span\n                    className={`text-[9px] font-mono uppercase tracking-[0.15em] px-2 py-1 rounded ${\n                      r.severity === \"high\"\n                        ? \"bg-[#EF4444]/15 text-[#EF4444]\"\n                        : \"bg-[#1F2937] text-[#94A3B8]\"\n                    }`}\n                  >\n                    {String(r.severity)}\n                  </span>\n                </div>\n\n                <p className=\"text-[10px] font-mono text-[#94A3B8] leading-relaxed mb-3\">\n                  {String(r.detail)}\n                </p>\n\n                {/* Nothing here froze anybody. A flag is a question for a\n                    person, and these two buttons are the answer. */}\n                <div className=\"grid grid-cols-2 gap-2\">\n                  <Act onClick={() => decideRisk(String(r.id), \"cleared\")} busy={working === r.id} tone=\"good\">\n                    Looks fine\n                  </Act>\n                  <Act onClick={() => decideRisk(String(r.id), \"escalated\")} busy={working === r.id} tone=\"bad\">\n                    Escalate\n                  </Act>\n                </div>\n              </div>\n            ))\n          )}\n\n          {risk.recent.length > 0 && (\n            <Panel title=\"Recently closed\">\n              {risk.recent.map((r, i) => (\n                <KV\n                  key={i}\n                  k={String(r.kind).replace(/_/g, \" \")}\n                  v={`${String(r.status)} · ${String(r.note ?? \"\")}`.slice(0, 48)}\n                  bad={r.status === \"escalated\"}\n                />\n              ))}\n            </Panel>\n          )}\n        </div>\n      )}\n\n      {tab === \"reserve\" && reserve && (\n        <div className=\"space-y-5\">\n          {/* Coverage is the only number on this page that can end the company.\n              It leads, and it is red the moment it drops under 100. */}\n          <div\n            className={`rounded-xl p-5 border ${\n              n(reserve.health.coverage_percent) >= 100\n                ? \"bg-[#10B981]/5 border-[#10B981]/30\"\n                : \"bg-[#EF4444]/10 border-[#EF4444]/40\"\n            }`}\n          >\n            <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1\">\n              Every KPC backed?\n            </p>\n            <p\n              className={`text-3xl font-black ${\n                n(reserve.health.coverage_percent) >= 100 ? \"text-[#10B981]\" : \"text-[#EF4444]\"\n              }`}\n            >\n              {reserve.health.coverage_percent == null\n                ? \"—\"\n                : `${n(reserve.health.coverage_percent).toFixed(2)}%`}\n            </p>\n            <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] mt-2 leading-relaxed\">\n              {money(reserve.health.total_backing)} held against{\" \"}\n              {money(reserve.health.owed_to_customers)} owed\n            </p>\n          </div>\n\n          {/* Liquid share: the books can balance and a withdrawal still fail. */}\n          {reserve.health.liquid_percent != null &&\n            n(reserve.health.liquid_percent) < n(reserve.health.liquid_floor_percent) && (\n              <div className=\"bg-[#EF4444]/10 border border-[#EF4444]/40 rounded-xl p-4 flex gap-3\">\n                <AlertTriangle size={16} className=\"text-[#EF4444] shrink-0 mt-0.5\" />\n                <p className=\"text-[10px] font-mono text-[#EF4444] uppercase tracking-[0.12em] leading-relaxed\">\n                  Only {n(reserve.health.liquid_percent).toFixed(1)}% liquid, under the{\" \"}\n                  {n(reserve.health.liquid_floor_percent).toFixed(0)}% floor. A withdrawal\n                  could fail even though the books balance.\n                </p>\n              </div>\n            )}\n\n          {/* Currency mismatch. Coverage above is measured at today's rate,\n              so a reserve held entirely in cedis reads 100% right up until\n              the cedi moves — and it has, from ~5.8 to ~12 against the\n              dollar between 2021 and 2024. This panel is the only place\n              that difference is visible. */}\n          {reserveFx?.has_reserve && reserveFx.by_tier && (\n            <>\n              <div\n                className={`rounded-xl p-4 border ${\n                  n(reserveFx.coverage_percent_stressed) >= 100\n                    ? \"bg-[#10B981]/5 border-[#10B981]/30\"\n                    : \"bg-[#EF4444]/10 border-[#EF4444]/40\"\n                }`}\n              >\n                <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.2em] mb-1\">\n                  Covered after a currency move?\n                </p>\n                <p\n                  className={`text-3xl font-black ${\n                    n(reserveFx.coverage_percent_stressed) >= 100\n                      ? \"text-[#10B981]\"\n                      : \"text-[#EF4444]\"\n                  }`}\n                >\n                  {reserveFx.coverage_percent_stressed == null\n                    ? \"—\"\n                    : `${n(reserveFx.coverage_percent_stressed).toFixed(2)}%`}\n                </p>\n                <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] mt-2 leading-relaxed\">\n                  {reserveFx.stress_case}\n                </p>\n                <p className=\"text-[10px] font-mono text-white uppercase tracking-[0.12em] mt-3 leading-relaxed\">\n                  {reserveFx.verdict}\n                </p>\n              </div>\n\n              <Panel title=\"What the reserve is made of\">\n                <KV\n                  k=\"In USD (the currency owed)\"\n                  v={`${money(reserveFx.by_tier.matched_usd)} · ${n(reserveFx.by_tier.matched_percent).toFixed(1)}%`}\n                  bad={n(reserveFx.by_tier.matched_percent) < 60}\n                />\n                {n(reserveFx.by_tier.hard) > 0 && (\n                  <KV\n                    k=\"Hard currency\"\n                    v={`${money(reserveFx.by_tier.hard)} · ${n(reserveFx.by_tier.hard_percent).toFixed(1)}%`}\n                  />\n                )}\n                <KV\n                  k=\"Soft currency\"\n                  v={`${money(reserveFx.by_tier.soft)} · ${n(reserveFx.by_tier.soft_percent).toFixed(1)}%`}\n                  bad={n(reserveFx.by_tier.soft_percent) > 25}\n                />\n                {n(reserveFx.buffer_needed_usd) > 0 && (\n                  <KV\n                    k=\"Buffer still needed\"\n                    v={`${money(reserveFx.buffer_needed_usd)} — hold ${n(reserveFx.coverage_needed_percent).toFixed(1)}% today`}\n                    bad\n                  />\n                )}\n                {(reserveFx.composition ?? []).map((c, i) => (\n                  <KV\n                    key={i}\n                    k={`${c.currency} (${c.tier})`}\n                    v={\n                      c.cannot_value\n                        ? \"no fresh rate — counts as zero backing\"\n                        : `${money(c.usd_value)} · ${n(c.share_percent).toFixed(1)}%`\n                    }\n                    bad={c.cannot_value}\n                  />\n                ))}\n              </Panel>\n\n              {(reserveFx.breaches ?? []).length > 0 && (\n                <Panel title=\"Policy breaches\">\n                  {(reserveFx.breaches ?? []).map((b, i) => (\n                    <div key={i} className=\"py-2 border-b border-[#1F2937] last:border-0\">\n                      <p className=\"text-[10px] font-bold text-[#EF4444]\">\n                        {b.says} — now {b.actual}\n                      </p>\n                      <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.12em] mt-1\">\n                        {b.fix}\n                      </p>\n                      <p className=\"text-[8px] font-mono text-[#4B5563] tracking-[0.12em] mt-0.5\">\n                        {b.setting}\n                      </p>\n                    </div>\n                  ))}\n                </Panel>\n              )}\n            </>\n          )}\n\n          <Panel title=\"Where the backing sits\">\n            <KV k=\"Liquid\" v={money(reserve.health.liquid)} />\n            <KV k=\"Deployed\" v={money(reserve.health.deployed)} />\n            <KV\n              k=\"Unrealised gain\"\n              v={money(reserve.health.unrealised_gain)}\n              bad={n(reserve.health.unrealised_gain) < 0}\n            />\n            <KV\n              k=\"Surplus\"\n              v={money(reserve.health.surplus_or_shortfall)}\n              bad={n(reserve.health.surplus_or_shortfall) < 0}\n            />\n          </Panel>\n\n          <Panel title=\"Does it pay for itself\">\n            <KV\n              k=\"Verdict\"\n              v={String(reserve.economics.verdict ?? \"—\")}\n              bad={String(reserve.economics.verdict ?? \"\").startsWith(\"LOSING\")}\n            />\n            <KV k=\"Savings book\" v={`${money(reserve.economics.savings_book)} KPC`} />\n            <KV\n              k=\"Owed to savers / year\"\n              v={`${money(reserve.economics.owed_to_savers_per_year)} KPC`}\n            />\n            <KV k=\"Reserve deployed\" v={money(reserve.economics.reserve_deployed)} />\n            {reserve.economics.reserve_yield_percent != null && (\n              <KV\n                k=\"Reserve yield\"\n                v={`${n(reserve.economics.reserve_yield_percent).toFixed(2)}% over ${n(\n                  reserve.economics.days_deployed,\n                ).toFixed(0)} days`}\n              />\n            )}\n            <KV k=\"Fee income to date\" v={money(reserve.economics.fee_income_to_date)} />\n          </Panel>\n\n          {reserve.deployments.length > 0 && (\n            <Panel title=\"Deployments\">\n              {reserve.deployments.map((d, i) => (\n                <KV\n                  key={i}\n                  k={String(d.name)}\n                  v={`${money(d.worth_now)} · ${n(d.unrealised) >= 0 ? \"+\" : \"\"}${money(\n                    d.unrealised,\n                  )}`}\n                  bad={n(d.unrealised) < 0}\n                />\n              ))}\n            </Panel>\n          )}\n        </div>\n      )}\n\n      {tab === \"rates\" && rates && (\n        <div className=\"space-y-5\">\n          <Panel title=\"What funds what\">\n            {rates.yields.map((y, i) => (\n              <KV\n                key={i}\n                k={`${y.bucket} (${y.basis})`}\n                v={`${(n(y.yield_bps) / 100).toFixed(2)}%`}\n              />\n            ))}\n          </Panel>\n\n          {rates.rates.map((r, i) => {\n            const losing = String(r.verdict ?? \"\").startsWith(\"LOSING\");\n            return (\n              <div\n                key={i}\n                className={`bg-[#111827] border rounded-xl p-4 ${\n                  losing ? \"border-[#EF4444]/50\" : \"border-[#1F2937]\"\n                }`}\n              >\n                <div className=\"flex justify-between items-start mb-2\">\n                  <div>\n                    <p className=\"text-sm font-bold capitalize\">{String(r.product)}</p>\n                    <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mt-0.5\">\n                      funded from {String(r.funded_from)} · {String(r.basis)}\n                    </p>\n                  </div>\n                  <p\n                    className={`text-xl font-black ${losing ? \"text-[#EF4444]\" : \"text-[#FDB813]\"}`}\n                  >\n                    {(n(r.current_bps) / 100).toFixed(2)}%\n                  </p>\n                </div>\n                <KV k=\"Funding yield\" v={`${(n(r.yield_bps) / 100).toFixed(2)}%`} />\n                <KV k=\"Most it can pay\" v={`${(n(r.max_bps) / 100).toFixed(2)}%`} />\n                <KV k=\"Target, with margin\" v={`${(n(r.ceiling_bps) / 100).toFixed(2)}%`} />\n                <p\n                  className={`text-[10px] font-mono uppercase tracking-[0.12em] mt-2 ${\n                    losing ? \"text-[#EF4444]\" : \"text-[#94A3B8]\"\n                  }`}\n                >\n                  {String(r.verdict)}\n                </p>\n              </div>\n            );\n          })}\n\n          {rates.history.length > 0 && (\n            <Panel title=\"Rate changes\">\n              {rates.history.map((h, i) => (\n                <KV\n                  key={i}\n                  k={`${h.product_id} ${h.from_bps == null ? \"\" : `${n(h.from_bps) / 100}% →`} ${\n                    n(h.to_bps) / 100\n                  }%`}\n                  v={h.forced ? `forced · ${String(h.reason ?? \"\")}` : \"within ceiling\"}\n                  bad={Boolean(h.forced)}\n                />\n              ))}\n            </Panel>\n          )}\n        </div>\n      )}\n\n      {tab === \"ops\" && ops && (\n        <div className=\"space-y-5\">\n          {/* Only the currencies that are actually switched on. Listing all\n              96 put 94 red \"off\" lines on the screen for currencies nobody\n              has enabled, which buried the one line that matters: an active\n              rate going stale. fx_rate() fails closed, so a stale rate stops\n              payments in that currency. */}\n          {/* Why each currency is not live. The old panel could say a\n              currency was off but not what was blocking it, so 94 rows of\n              \"off\" looked like a setting nobody had flipped rather than a\n              closed loop: no rate meant never refreshed, and never refreshed\n              meant no rate. (035) */}\n          {currencies && (\n            <Panel title=\"Currency pipeline\">\n              <KV k=\"On the books\" v={String(currencies.summary.total)} />\n              <KV\n                k=\"Switched on\"\n                v={String(currencies.summary.switched_on)}\n                bad={currencies.summary.switched_on < 3}\n              />\n              <KV k=\"Can be priced\" v={String(currencies.summary.can_be_valued)} />\n              <KV\n                k=\"Can take money in\"\n                v={String(currencies.summary.can_take_money_in)}\n                bad={currencies.summary.can_take_money_in === 0}\n              />\n              {currencies.summary.rate_too_old > 0 && (\n                <KV\n                  k=\"Live but rate too old\"\n                  v={`${currencies.summary.rate_too_old} — payments in these are refused`}\n                  bad\n                />\n              )}\n              {currencies.summary.no_rate_yet > 0 && (\n                <KV\n                  k=\"Never had a rate\"\n                  v={`${currencies.summary.no_rate_yet} — run the FX refresh`}\n                  bad\n                />\n              )}\n              {Object.entries(\n                (currencies.rows ?? []).reduce<Record<string, number>>((acc, r) => {\n                  acc[r.blocked_by] = (acc[r.blocked_by] ?? 0) + 1;\n                  return acc;\n                }, {}),\n              )\n                .sort((a, b) => b[1] - a[1])\n                .map(([reason, count]) => (\n                  <KV key={reason} k={reason} v={String(count)} />\n                ))}\n            </Panel>\n          )}\n\n          <Panel title=\"Exchange rates\">\n            {ops.fx\n              .filter((f) => f.state !== \"switched off\")\n              .map((f, i) => {\n                const hours = Math.round(n(f.age_minutes) / 60);\n                const pegged = f.state === \"the peg\";\n                // 48h is where fx_rate() refuses. Warn with a day to spare.\n                const stale = !pegged && hours >= 24;\n                return (\n                  <KV\n                    key={i}\n                    k={String(f.code)}\n                    v={`${n(f.units_per_usd).toLocaleString()} / $ · ${\n                      pegged ? \"pegged\" : `${hours}h old`\n                    }`}\n                    bad={stale}\n                  />\n                );\n              })}\n            {(() => {\n              const off = ops.fx.filter((f) => f.state === \"switched off\").length;\n              const stale = ops.fx.filter(\n                (f) => f.state === \"usable\" && n(f.age_minutes) >= 24 * 60,\n              ).length;\n              return (\n                <>\n                  {stale > 0 && (\n                    <p className=\"text-[9px] font-mono text-[#EF4444] uppercase tracking-[0.12em] mt-3 pt-3 border-t border-[#1F2937] leading-relaxed\">\n                      {stale} rate{stale === 1 ? \"\" : \"s\"} over a day old. At 48 hours\n                      payments in {stale === 1 ? \"that currency\" : \"those currencies\"}{\" \"}\n                      stop.\n                    </p>\n                  )}\n                  {off > 0 && (\n                    <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.12em] mt-3 pt-3 border-t border-[#1F2937]\">\n                      {off} other currencies not switched on\n                    </p>\n                  )}\n                </>\n              );\n            })()}\n          </Panel>\n\n          <Panel title=\"Nightly jobs\">\n            {ops.jobs.length === 0 ? (\n              <p className=\"text-[9px] font-mono text-[#4B5563] uppercase tracking-[0.15em] py-2\">\n                No runs recorded yet\n              </p>\n            ) : (\n              ops.jobs.map((j, i) => (\n                <KV\n                  key={i}\n                  k={`${j.step ?? j.job} · ${since(String(j.ran_at))}`}\n                  v={j.ok ? `ok · ${n(j.ms)}ms` : String(j.detail ?? \"failed\")}\n                  bad={!j.ok}\n                />\n              ))\n            )}\n          </Panel>\n        </div>\n      )}\n    </Shell>\n  );\n}\n\nfunction Shell({ children }: { children: React.ReactNode }) {\n  return (\n    <div className=\"min-h-[100dvh] bg-[#0A0E14] text-white font-sans p-5 selection:bg-[#AA771C]/30\">\n      <div className=\"max-w-xl mx-auto\">\n        <div className=\"flex items-center gap-3 mb-6\">\n          <Link\n            href=\"/wallet\"\n            className=\"text-[#94A3B8] hover:text-[#FDB813] p-2 bg-[#1F2937] rounded-lg border border-[#374151]\"\n          >\n            <ArrowLeft size={18} />\n          </Link>\n          <h1 className=\"text-lg font-black uppercase tracking-widest\">Operations</h1>\n        </div>\n        {children}\n      </div>\n    </div>\n  );\n}\n\nconst kpcShort = (v: unknown) =>\n  `${Number(v ?? 0).toLocaleString(undefined, { maximumFractionDigits: 0 })} KPC`;\n\nfunction Panel({ title, children }: { title: string; children: React.ReactNode }) {\n  return (\n    <div className=\"bg-[#111827] border border-[#1F2937] rounded-xl p-4\">\n      <p className=\"text-[9px] font-mono text-[#FDB813] uppercase tracking-[0.2em] mb-3\">\n        {title}\n      </p>\n      <div className=\"space-y-1.5\">{children}</div>\n    </div>\n  );\n}\n\nfunction KV({ k, v, bad }: { k: string; v: string; bad?: boolean }) {\n  return (\n    <div className=\"flex justify-between items-baseline gap-3\">\n      <span className=\"text-[10px] font-mono text-[#94A3B8] uppercase tracking-[0.12em]\">{k}</span>\n      <span\n        className={`text-xs font-mono font-bold ${bad ? \"text-[#EF4444]\" : \"text-white\"}`}\n      >\n        {v}\n      </span>\n    </div>\n  );\n}\n\nfunction Stat({ label, value, bad }: { label: string; value: string; bad?: boolean }) {\n  return (\n    <div className=\"bg-[#111827] border border-[#1F2937] rounded-xl p-3\">\n      <p className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] mb-1\">\n        {label}\n      </p>\n      <p className={`text-sm font-black ${bad ? \"text-[#EF4444]\" : \"text-white\"}`}>{value}</p>\n    </div>\n  );\n}\n\nfunction Act({\n  children,\n  onClick,\n  busy,\n  tone,\n}: {\n  children: React.ReactNode;\n  onClick: () => void;\n  busy: boolean;\n  tone?: \"good\" | \"bad\";\n}) {\n  const colour =\n    tone === \"good\"\n      ? \"hover:bg-[#10B981]/15 hover:border-[#10B981]/50 hover:text-[#10B981]\"\n      : tone === \"bad\"\n        ? \"hover:bg-[#EF4444]/15 hover:border-[#EF4444]/50 hover:text-[#EF4444]\"\n        : \"hover:bg-[#FDB813]/10 hover:border-[#FDB813]/50 hover:text-[#FDB813]\";\n  return (\n    <button\n      disabled={busy}\n      onClick={onClick}\n      className={`flex items-center justify-center gap-1.5 py-2.5 bg-[#1F2937] border border-[#374151] text-[#94A3B8] rounded-lg text-[9px] font-mono uppercase tracking-[0.12em] transition-colors disabled:opacity-40 ${colour}`}\n    >\n      {busy && <Loader2 size={11} className=\"animate-spin\" />}\n      {children}\n    </button>\n  );\n}\n\nfunction Empty({ children }: { children: React.ReactNode }) {\n  return (\n    <div className=\"flex items-center justify-center gap-2 py-12 text-[10px] font-mono uppercase tracking-[0.15em] text-[#4B5563]\">\n      <Check size={14} /> {children}\n    </div>\n  );\n}\n", true);

write("app/api/cron/fx/route.ts", "import { NextResponse } from \"next/server\";\nimport { supabaseAdmin } from \"@/app/lib/supabaseServer\";\n\n// Daily FX refresh.\n//\n// WHY THIS EXISTS\n//\n// fx_rate() fails closed: past price_max_age it raises rather than guessing.\n// That is the right design, but it means a rate nobody refreshes does not\n// degrade — it stops payments in that currency outright. Until now nothing\n// refreshed anything. The GHS rate was set by hand and was counting down.\n//\n// WHY A BAD RATE IS WORSE THAN A STALE ONE\n//\n// A stale rate stops payments, loudly. A WRONG rate prices every payment\n// wrongly, silently, until somebody notices the money does not add up. So\n// this refuses more often than it accepts:\n//\n//   - the provider must say it succeeded\n//   - the rate must be a finite number greater than zero\n//   - it must be within MAX_MOVE of the rate we already hold\n//\n// A currency that fails any of those keeps its old rate and is reported. If\n// the old rate then goes stale, payments stop — which is the correct failure,\n// because at that point we genuinely do not know the price.\n\nexport const dynamic = \"force-dynamic\";\n\n// A real currency can move several percent in a day. It does not move 25%\n// without something being wrong with either the country or the feed, and\n// this cannot tell which — so it stops and asks for a human.\nconst MAX_MOVE = 0.25;\n\nconst PROVIDER = \"https://open.er-api.com/v6/latest/USD\";\n\ntype Outcome = {\n  code: string;\n  from: number | null;\n  to: number | null;\n  status: \"updated\" | \"seeded\" | \"unchanged\" | \"rejected\" | \"missing\";\n  why?: string;\n};\n\nexport async function GET(request: Request) {\n  // Vercel Cron sends this header when CRON_SECRET is set. Without the check\n  // the endpoint is a public button that repoints every exchange rate.\n  const secret = process.env.CRON_SECRET;\n  if (secret) {\n    const auth = request.headers.get(\"authorization\");\n    if (auth !== `Bearer ${secret}`) {\n      return NextResponse.json({ error: \"Unauthorized\" }, { status: 401 });\n    }\n  }\n\n  let payload: { result?: string; rates?: Record<string, number> };\n  try {\n    const res = await fetch(PROVIDER, { cache: \"no-store\" });\n    if (!res.ok) {\n      return NextResponse.json(\n        { error: `rate provider returned ${res.status}`, updated: 0 },\n        { status: 502 },\n      );\n    }\n    payload = await res.json();\n  } catch (err) {\n    console.error(\"fx cron: provider unreachable\", err);\n    return NextResponse.json({ error: \"rate provider unreachable\", updated: 0 }, { status: 502 });\n  }\n\n  if (payload.result && payload.result !== \"success\") {\n    return NextResponse.json({ error: `provider said ${payload.result}`, updated: 0 }, { status: 502 });\n  }\n  const rates = payload.rates;\n  if (!rates || typeof rates !== \"object\") {\n    return NextResponse.json({ error: \"provider returned no rates\", updated: 0 }, { status: 502 });\n  }\n\n  // EVERY currency on the books, not just the switched-on ones.\n  //\n  // This used to intersect fx_rates with the active currencies, on the\n  // reasoning that writing rates for currencies nothing can be charged in\n  // widens the blast radius of a bad feed for no benefit. The benefit turned\n  // out to be the whole product. That filter was a closed loop:\n  //\n  //   a currency with no rate was never refreshed, so it never got a rate\n  //   fx_rate() raises for a switched-off currency, so it could not be\n  //   switched on until it had one\n  //\n  // Ninety-four currencies sat in the table unable to escape it, and the\n  // landing page printed \"Currencies: 1\" under \"Send Globally\" as a result.\n  //\n  // The blast-radius worry is still answered, just not by this filter: a\n  // rate only decides what KobPay can quote, hold and send. Taking money in\n  // additionally needs an active payment provider carrying the code\n  // (chargeable_currencies), and widening rates does not add one.\n  const [{ data: held, error: heldErr }, { data: known, error: knownErr }] = await Promise.all([\n    supabaseAdmin.from(\"fx_rates\").select(\"currency, units_per_usd\"),\n    supabaseAdmin.from(\"currencies\").select(\"code, active\"),\n  ]);\n\n  if (heldErr || knownErr) {\n    console.error(\"fx cron: cannot read current rates\", heldErr ?? knownErr);\n    return NextResponse.json({ error: \"cannot read current rates\", updated: 0 }, { status: 500 });\n  }\n\n  const prevByCode = new Map(\n    (held ?? []).map((r) => [String(r.currency), Number(r.units_per_usd)]),\n  );\n\n  const outcomes: Outcome[] = [];\n\n  for (const row of known ?? []) {\n    const code = String(row.code);\n\n    // USD is the peg, not a quote. Nothing to refresh.\n    if (code === \"USD\") continue;\n\n    const next = Number(rates[code]);\n    const prev = prevByCode.has(code) ? Number(prevByCode.get(code)) : NaN;\n\n    if (!Number.isFinite(next) || next <= 0) {\n      outcomes.push({\n        code,\n        from: Number.isFinite(prev) ? prev : null,\n        to: null,\n        status: \"missing\",\n        why: \"provider has no usable rate\",\n      });\n      continue;\n    }\n\n    if (Number.isFinite(prev) && prev > 0) {\n      const move = Math.abs(next - prev) / prev;\n      if (move > MAX_MOVE) {\n        outcomes.push({\n          code,\n          from: prev,\n          to: next,\n          status: \"rejected\",\n          why: `moved ${(move * 100).toFixed(1)}% — kept the old rate`,\n        });\n        continue;\n      }\n      // Writing an identical rate every day buries real changes in history.\n      if (move === 0) {\n        outcomes.push({ code, from: prev, to: next, status: \"unchanged\" });\n        continue;\n      }\n    }\n\n    const { error } = await supabaseAdmin.rpc(\"fx_set_rate\", {\n      p_currency: code,\n      p_units_per_usd: next,\n      p_source: \"open.er-api.com daily\",\n    });\n\n    if (error) {\n      outcomes.push({\n        code,\n        from: Number.isFinite(prev) ? prev : null,\n        to: next,\n        status: \"rejected\",\n        why: error.message,\n      });\n      continue;\n    }\n    outcomes.push({\n      code,\n      from: Number.isFinite(prev) ? prev : null,\n      to: next,\n      // A currency getting its first rate is worth telling apart from one\n      // being refreshed: it is a currency entering the product.\n      status: Number.isFinite(prev) ? \"updated\" : \"seeded\",\n    });\n  }\n\n  // Now that rates exist, switch on whatever has become usable. Holding and\n  // pricing only — chargeable_currencies() still gates taking money in. (035)\n  let activated: unknown = null;\n  const { data: act, error: actErr } = await supabaseAdmin.rpc(\"activate_priced_currencies\");\n  if (actErr) {\n    console.error(\"fx cron: could not activate priced currencies\", actErr);\n  } else {\n    activated = act;\n  }\n\n  const updated = outcomes.filter((o) => o.status === \"updated\").length;\n  const seeded = outcomes.filter((o) => o.status === \"seeded\").length;\n  const problems = outcomes.filter((o) => o.status === \"rejected\" || o.status === \"missing\");\n\n  // Rejections are the interesting case: the rate is now ageing toward the\n  // point where it stops payments, and only a human can decide why the feed\n  // disagreed with us.\n  if (problems.length > 0) {\n    console.error(\"fx cron: rates not refreshed\", problems);\n  }\n\n  return NextResponse.json({\n    updated,\n    seeded,\n    activated,\n    problems: problems.length,\n    outcomes,\n    at: new Date().toISOString(),\n  });\n}\n", true);

write("app/dashboard/ClientDashboard.tsx", "// app/dashboard/ClientDashboard.tsx\n\"use client\";\n\nimport React, { useEffect, useState, useRef } from 'react';\nimport Link from 'next/link';\nimport { usePathname } from 'next/navigation';\nimport { motion, AnimatePresence, useMotionValue, useTransform, animate } from 'framer-motion';\nimport { translations, LanguageCode } from '../translations';\nimport { \n  LayoutDashboard, Search, Wallet, TrendingUp, Send, \n  ShoppingCart, BarChart2, Layers, Code, Shield, User, Globe,\n  Activity, Globe2, Menu, X, ChevronDown, ChevronRight, Zap, Lock, Server, Coins,\n  BarChart, PieChart, Users, HardDrive, Loader2,\n  PiggyBank, LineChart as LineChartIcon, Receipt, ShieldCheck, Store, Scale, Gauge\n} from 'lucide-react';\nimport { \n  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend \n} from 'recharts';\nimport { ConnectButton } from '@rainbow-me/rainbowkit';\nimport toast, { Toaster } from 'react-hot-toast';\nimport BuyKpcModal from '../components/BuyKpcModal';\nimport { supabase } from '../lib/supabaseClient';\n\n// --- HYDRATION SHIELD ---\nconst useIsMounted = () => {\n  const [mounted, setMounted] = useState(false);\n  useEffect(() => setMounted(true), []);\n  return mounted;\n};\n\n// --- THE ENGINE: ROLLING MONOSPACE NUMBERS ---\nfunction RollingNum({ value, decimals = 0, prefix = \"\", suffix = \"\" }: { value: number, decimals?: number, prefix?: string, suffix?: string }) {\n  const count = useMotionValue(0);\n  const rounded = useTransform(count, (latest) => \n    `${prefix}${new Intl.NumberFormat('en-US', { minimumFractionDigits: decimals, maximumFractionDigits: decimals }).format(latest)}${suffix}`\n  );\n  useEffect(() => {\n    const controls = animate(count, value, { duration: 2.5, ease: [0.16, 1, 0.3, 1] });\n    return controls.stop;\n  }, [value, count]);\n  return <motion.span className=\"font-mono tracking-tighter\">{rounded}</motion.span>;\n}\n\n// --- INITIAL CHART DATA ---\nconst initialChartData = [\n  { month: 'Jan 24', KPC: 1.00, GHS: 1.00, NGN: 1.00, ZAR: 1.00 },\n  { month: 'Apr 24', KPC: 1.00, GHS: 0.88, NGN: 0.75, ZAR: 0.92 },\n  { month: 'Jul 24', KPC: 1.00, GHS: 0.76, NGN: 0.55, ZAR: 0.85 },\n  { month: 'Oct 24', KPC: 1.00, GHS: 0.65, NGN: 0.40, ZAR: 0.78 },\n  { month: 'Jan 25', KPC: 1.00, GHS: 0.60, NGN: 0.35, ZAR: 0.75 },\n  { month: 'Current', KPC: 1.00, GHS: 0.55, NGN: 0.30, ZAR: 0.70 },\n];\n\nconst initialTxns = [\n  { id: \"tx1\", hash: \"0x8f...3c9a\", from: \"0x12...99a1\", to: \"0x44...bb2c\", amount: 1500, type: \"TRANSFER\", app: \"KobPay Coins\", time: \"Just now\" },\n  { id: \"tx2\", hash: \"0x2a...11f8\", from: \"0x77...ee33\", to: \"0x99...dd44\", amount: 32, type: \"SUBSCRIPTION\", app: \"KobBot\", time: \"2s ago\" },\n  { id: \"tx3\", hash: \"0x9c...bb21\", from: \"0x22...cc11\", to: \"0x55...ff88\", amount: 45000, type: \"ESCROW\", app: \"Ready Markets\", time: \"5s ago\" },\n  { id: \"tx4\", hash: \"0x1d...aa44\", from: \"0x88...dd22\", to: \"0x33...aa99\", amount: 250, type: \"REWARD\", app: \"KobPlay\", time: \"8s ago\" },\n  { id: \"tx5\", hash: \"0x5e...cc77\", from: \"0x44...aa55\", to: \"0x11...bb66\", amount: 8900, type: \"TRANSFER\", app: \"Direct\", time: \"12s ago\" },\n];\n\n// Was six invented products carrying invented metrics, scrolling across the\n// top of a live payments site:\n//\n//   KobBot 2.0 — 2,341 active today      Axiom Oracle — 892 users today\n//   KobPlay — 45,230 KC earned           RANKR LIVE — 12,450 rankings\n//   Ready Markets — 1,204 KPC escrow     AegisProp — 14,000 KPC settled\n//\n// None of those apps exist. Two apps are registered on the rail, and neither\n// is named there. A regulator reading that banner alongside the ledger finds\n// six products and ~76,000 KPC of activity that cannot be reconciled to\n// anything — which is a representation, not decoration.\n//\n// Replaced with facts the ledger can produce. Anything still at zero is left\n// out rather than printed as \"0 countries\", so the banner is short before\n// launch and grows on its own.\nconst staticTickerItems = [\n  \"⚡ 1 KPC = $1.00, always\",\n  \"💸 Sending KPC is free\",\n  \"🔍 Reserve published on the Ledger page\",\n];\n\nconst drawerContent: Record<string, any> = {\n  \"buy\": { title: \"Acquire KPC\", subtitle: \"Mint Sovereign Asset\", icon: <Coins className=\"text-[#FDB813]\" size={24} />, color: \"text-[#FDB813]\", bg: \"bg-[#FDB813]/10\", border: \"border-[#FDB813]/30\", details: \"Instantly mint 1:1 USD-backed KPC via fiat gateway.\", metrics: [] },\n  \"live_price\": { title: \"Price Oracle\", subtitle: \"Peg Stability\", icon: <Activity className=\"text-[#10B981]\" size={24} />, color: \"text-[#10B981]\", bg: \"bg-[#10B981]/10\", border: \"border-[#10B981]/30\", details: \"Aggregate price feed from decentralized nodes.\", metrics: [] },\n  \"volume\": { title: \"24H Volume\", subtitle: \"Network Velocity\", icon: <BarChart className=\"text-[#22D3EE]\" size={24} />, color: \"text-[#22D3EE]\", bg: \"bg-[#22D3EE]/10\", border: \"border-[#22D3EE]/30\", details: \"Total volume transacted across the Sovereign Rail.\", metrics: [] },\n  \"market_cap\": { title: \"Market Cap\", subtitle: \"Value Secured\", icon: <PieChart className=\"text-[#FDB813]\" size={24} />, color: \"text-[#FDB813]\", bg: \"bg-[#FDB813]/10\", border: \"border-[#FDB813]/30\", details: \"Total market value of circulating KPC supply.\", metrics: [] },\n  \"txns\": { title: \"Transactions\", subtitle: \"Daily Execution\", icon: <Zap className=\"text-[#8B5CF6]\" size={24} />, color: \"text-[#8B5CF6]\", bg: \"bg-[#8B5CF6]/10\", border: \"border-[#8B5CF6]/30\", details: \"Successfully settled transactions on network today.\", metrics: [] },\n  \"holders\": { title: \"Holders\", subtitle: \"Global Distribution\", icon: <Users className=\"text-[#F472B6]\" size={24} />, color: \"text-[#F472B6]\", bg: \"bg-[#F472B6]/10\", border: \"border-[#F472B6]/30\", details: \"Unique wallet addresses currently holding KPC.\", metrics: [] },\n  \"network\": { title: \"Network\", subtitle: \"Infrastructure Health\", icon: <HardDrive className=\"text-[#10B981]\" size={24} />, color: \"text-[#10B981]\", bg: \"bg-[#10B981]/10\", border: \"border-[#10B981]/30\", details: \"Live status of validators and consensus health.\", metrics: [] },\n  \"fee\": { title: \"Avg Fee\", subtitle: \"Settlement Costs\", icon: <Code className=\"text-[#94A3B8]\" size={24} />, color: \"text-[#94A3B8]\", bg: \"bg-[#1F2937]/50\", border: \"border-[#374151]/50\", details: \"Average gas cost for micro-transactions.\", metrics: [] },\n  \"circulating\": { title: \"Supply\", subtitle: \"Token Emission\", icon: <Layers className=\"text-[#FDB813]\" size={24} />, color: \"text-[#FDB813]\", bg: \"bg-[#FDB813]/10\", border: \"border-[#FDB813]/30\", details: \"Net amount of KPC accessible across all platforms.\", metrics: [] },\n  \"global\": { title: \"Global Settlement\", subtitle: \"Cross-Border Liquidity\", icon: <Globe2 className=\"text-[#22D3EE]\" size={24} />, color: \"text-[#22D3EE]\", bg: \"bg-[#22D3EE]/10\", border: \"border-[#22D3EE]/30\", details: \"Native borderless rail settling in milliseconds.\", metrics: [] },\n  \"hedge\": { title: \"Sovereign Savings\", subtitle: \"Value Protection\", icon: <Shield className=\"text-[#FDB813]\" size={24} />, color: \"text-[#FDB813]\", bg: \"bg-[#FDB813]/10\", border: \"border-[#FDB813]/30\", details: \"Asset designed to protect users from fiat depreciation.\", metrics: [] },\n  \"earn\": { title: \"Action Yield\", subtitle: \"Proof-of-Engagement\", icon: <TrendingUp className=\"text-[#10B981]\" size={24} />, color: \"text-[#10B981]\", bg: \"bg-[#10B981]/10\", border: \"border-[#10B981]/30\", details: \"Generate KC through network participation.\", metrics: [] },\n  \"pay\": { title: \"Universal Pay\", subtitle: \"Ecosystem Commerce\", icon: <ShoppingCart className=\"text-[#8B5CF6]\" size={24} />, color: \"#8B5CF6\", bg: \"bg-[#8B5CF6]/10\", border: \"border-[#8B5CF6]/30\", details: \"One currency for all integrated dApps.\", metrics: [] },\n  \"protect\": { title: \"Protect Savings\", subtitle: \"Fiat-to-Peg Swap\", icon: <Lock className=\"text-[#10B981]\" size={24} />, color: \"text-[#10B981]\", bg: \"bg-[#10B981]/10\", border: \"border-[#10B981]/30\", details: \"Shield local currency by minting KPC.\", metrics: [] }\n};\n\nexport default function KPCSovereignDashboard() {\n  const mounted = useIsMounted();\n  const pathname = usePathname(); \n  const [isBuyModalOpen, setIsBuyModalOpen] = useState(false);\n  const [currentUser, setCurrentUser] = useState<{ id: string; email: string; accessToken: string } | null>(null);\n\n  useEffect(() => {\n    supabase.auth.getSession().then(({ data }) => {\n      if (data.session) {\n        setCurrentUser({\n          id: data.session.user.id,\n          email: data.session.user.email ?? '',\n          accessToken: data.session.access_token,\n        });\n      }\n    });\n  }, []);\n  \n  const [liveChartData, setLiveChartData] = useState(initialChartData);\n  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);\n  // Staff-only nav entry. am_i_staff() is the same gate the admin readers\n  // use, so this can never show a door that will not open — and the page\n  // enforces it server-side regardless of what the client believes.\n  const [isStaff, setIsStaff] = useState(false);\n\n  useEffect(() => {\n    supabase.auth.getSession().then(({ data }) => {\n      if (!data.session) return;\n      supabase.rpc(\"am_i_staff\").then(({ data: staff }) => setIsStaff(Boolean(staff)));\n    });\n  }, []);\n  const [activeDrawer, setActiveDrawer] = useState<string | null>(null);\n  const [liveTxns, setLiveTxns] = useState(initialTxns);\n\n  // Was: the latest Ethereum block height, polled from a public RPC and\n  // printed as \"MAINNET: #26227870\" — a number from a chain KobPay does not\n  // run, has no account on, and settles nothing through. \"NETWORK: OFFLINE\"\n  // meant that RPC was unreachable, which said nothing about whether KobPay\n  // was up. Now it reports whether our own ledger answered.\n  const [ledgerLive, setLedgerLive] = useState<boolean | null>(null);\n  // These were hardcoded: 84,210 holders, $12.4M volume, 142,850 daily\n  // transactions, 54 corridors, 23 apps, 450 merchants. The ledger said 2\n  // profiles and 2 apps. Published figures a regulator can test against the\n  // database are representations, not marketing — so they now come from\n  // public_stats(), which counts from the ledger at call time.\n  //\n  // Zeros until Paystack settles the first real deposit. That is the correct\n  // reading, and every one of them moves the day it does.\n  const [networkStats, setNetworkStats] = useState({\n    price: 1.00,\n    volume: 0,\n    marketCap: 0,\n    txnsToday: 0,\n    holders: 0,\n    circulating: 0,\n    corridors: 0,\n    countries: 0,\n    transferFeeBps: 0,\n    activeApps: 0,\n    merchants: 0\n  });\n\n  useEffect(() => {\n    supabase.rpc(\"public_stats\").then(({ data }) => {\n      if (!data) { setLedgerLive(false); return; }\n      setLedgerLive(true);\n      const d = data as Record<string, number>;\n      setNetworkStats((prev) => ({\n        ...prev,\n        price: Number(d.price_usd ?? 1),\n        volume: Number(d.volume_24h ?? 0),\n        // Market cap for a pegged unit is simply what exists, times $1.\n        marketCap: Number(d.total_supply ?? 0),\n        txnsToday: Number(d.transactions_24h ?? 0),\n        holders: Number(d.holders ?? 0),\n        circulating: Number(d.in_circulation ?? 0),\n        // The \"Send Globally\" card was reading currencies_supported, which\n        // counts what you can FUND an account in — one provider, Paystack,\n        // GHS, so: 1. Sending has nothing to do with Paystack; KPC moves on\n        // our own ledger between two phone numbers. currencies_priced is the\n        // number that belongs under a claim about sending. (033)\n        corridors: Number(d.currencies_priced ?? d.currencies_supported ?? 0),\n        countries: Number(d.countries ?? 0),\n        transferFeeBps: Number(d.transfer_fee_bps ?? 0),\n        activeApps: Number(d.apps ?? 0),\n        merchants: Number(d.merchants ?? 0),\n      }));\n    });\n  }, []);\n\n  // Only facts with a number behind them. A zero is dropped, not printed.\n  const tickerItems = React.useMemo(() => {\n    const live: string[] = [];\n    if (networkStats.countries > 0) live.push(`🌍 ${networkStats.countries} countries`);\n    if (networkStats.corridors > 0) live.push(`💱 ${networkStats.corridors} currencies priced`);\n    if (networkStats.holders > 0) live.push(`👥 ${networkStats.holders.toLocaleString()} wallets holding KPC`);\n    if (networkStats.activeApps > 0) live.push(`📱 ${networkStats.activeApps} apps on the rail`);\n    if (networkStats.merchants > 0) live.push(`🛒 ${networkStats.merchants} businesses accepting KPC`);\n    return [...staticTickerItems, ...live];\n  }, [networkStats]);\n\n  const [currentLang, setCurrentLang] = useState<LanguageCode>('en');\n  const [isLangMenuOpen, setIsLangMenuOpen] = useState(false);\n  const t = translations[currentLang];\n\n  // REMOVED: a 12-second poll of a public Ethereum RPC that, on every tick,\n  // did this to the figures 025 had just made honest —\n  //\n  //   txnsToday: prev.txnsToday + Math.floor(Math.random() * 5),\n  //   holders:   prev.holders   + (blockNum % 5 === 0 ? 1 : 0),\n  //   volume:    prev.volume    + (Math.random() * 500)\n  //\n  // So the counts came from the ledger and were then walked upward by random\n  // numbers, every twelve seconds, for as long as the tab stayed open. Leave\n  // the page open an hour and it invents roughly 150,000 KPC of volume and\n  // several hundred payments that never happened. That is the exact thing\n  // 025 was written to stop, and it was undoing it on the client.\n  //\n  // Nothing replaces it. The figures move when the ledger moves.\n  useEffect(() => {\n    const refresh = setInterval(() => {\n      supabase.rpc(\"public_stats\").then(({ data }) => {\n        if (!data) return;\n        const d = data as Record<string, number>;\n        setNetworkStats((prev) => ({\n          ...prev,\n          volume: Number(d.volume_24h ?? prev.volume),\n          txnsToday: Number(d.transactions_24h ?? prev.txnsToday),\n          holders: Number(d.holders ?? prev.holders),\n          circulating: Number(d.in_circulation ?? prev.circulating),\n          marketCap: Number(d.total_supply ?? prev.marketCap),\n        }));\n      });\n    }, 60000);\n    return () => clearInterval(refresh);\n  }, []);\n\n  useEffect(() => {\n    const chartInterval = setInterval(() => {\n      setLiveChartData(prev => {\n        const newData = [...prev];\n        const last = { ...newData[newData.length - 1] };\n        last.GHS = Math.max(0.1, last.GHS + (Math.random() * 0.02 - 0.01));\n        last.NGN = Math.max(0.1, last.NGN + (Math.random() * 0.02 - 0.01));\n        last.ZAR = Math.max(0.1, last.ZAR + (Math.random() * 0.02 - 0.01));\n        newData[newData.length - 1] = last;\n        return newData;\n      });\n    }, 2500);\n\n    const generateTxn = () => {\n      setLiveTxns(prev => {\n        const types = [\"TRANSFER\", \"ESCROW\", \"SWAP\", \"MINT\", \"REWARD\"];\n        const apps = [\"KobPay Coins\", \"Ready Markets\", \"KobPlay\", \"Axiom\", \"Direct\"];\n        const newTxn = {\n          id: `tx-${Date.now()}`,\n          hash: `0x${Math.random().toString(16).slice(2, 10)}`,\n          from: `0x${Math.random().toString(16).slice(2, 6)}..${Math.random().toString(16).slice(2, 6)}`,\n          to: `0x${Math.random().toString(16).slice(2, 6)}..${Math.random().toString(16).slice(2, 6)}`,\n          amount: Math.floor(Math.random() * 25000) + 10,\n          type: types[Math.floor(Math.random() * types.length)],\n          app: apps[Math.floor(Math.random() * apps.length)],\n          time: \"Just now\"\n        };\n        return [newTxn, ...prev.slice(0, 5)];\n      });\n      setTimeout(generateTxn, Math.random() * 1700 + 800);\n    };\n\n    const initialTimeout = setTimeout(generateTxn, 1000);\n\n    return () => {\n      clearInterval(chartInterval);\n      clearTimeout(initialTimeout);\n    };\n  }, []);\n\n  useEffect(() => {\n    if (isMobileMenuOpen || activeDrawer) {\n      document.body.style.overflow = 'hidden';\n    } else {\n      document.body.style.overflow = 'unset';\n    }\n  }, [isMobileMenuOpen, activeDrawer]);\n\n  const handleFeatureClick = (featureName: string) => {\n    setIsMobileMenuOpen(false);\n    toast(`Connecting to ${featureName} Protocol...`, {\n      icon: '⚡',\n      style: { borderRadius: '10px', background: '#111827', color: '#fff', border: '1px solid #1F2937', fontSize: '12px', fontFamily: 'monospace' }\n    });\n  };\n\n  const handleExecuteFunction = () => {\n    toast.success('Sovereign Contract Executed via Reown', {\n      icon: '✅',\n      style: { borderRadius: '10px', background: '#10B981', color: '#0A0E14', fontWeight: 'bold', fontSize: '12px', fontFamily: 'monospace' }\n    });\n    setActiveDrawer(null); \n  };\n\n  if (!mounted) return <div className=\"min-h-[100dvh] bg-[#0A0E14]\" />;\n  const activeDrawerData = activeDrawer ? drawerContent[activeDrawer] : null;\n\n  return (\n    <div className=\"flex h-[100dvh] bg-[#0A0E14] text-[#F9FAFB] font-sans overflow-hidden selection:bg-[#AA771C]/30 relative\">\n      <Toaster position=\"top-center\" reverseOrder={false} />\n      \n      <aside className={`fixed inset-y-0 left-0 w-64 bg-[#111827] border-r border-[#1F2937] flex flex-col justify-between z-50 transform ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 transition-transform duration-300 ease-in-out shrink-0`}>\n        <div className=\"flex-1 overflow-y-auto [&::-webkit-scrollbar]:hidden\">\n          <div className=\"p-4 lg:p-6 border-b border-[#1F2937] flex items-center justify-between\">\n            <div className=\"flex items-center gap-3\">\n              <div className=\"w-8 h-8 rounded-full bg-gradient-to-br from-[#FDB813] to-[#F59E0B] flex items-center justify-center shadow-[0_0_15px_rgba(253,184,19,0.4)] shrink-0\"><span className=\"font-black text-[#0A0E14]\">K</span></div>\n              <div className=\"flex flex-col\"><h2 className=\"font-black text-[13px] tracking-widest uppercase leading-none mb-1.5 whitespace-nowrap\">KOBPAY COINS</h2><p className=\"text-[8px] font-mono text-[#FDB813] tracking-[0.45em] uppercase leading-none\">Sovereign Rail</p></div>\n            </div>\n            <button className=\"lg:hidden text-[#94A3B8] hover:text-white\" onClick={() => setIsMobileMenuOpen(false)}>\n              <X size={20} />\n            </button>\n          </div>\n          <nav className=\"p-3 lg:p-4 pb-8 space-y-0.5 lg:space-y-1\">\n            {/* Grouped, because a flat list of fifteen is a list nobody\n                reads. The money features were previously reachable only from\n                /wallet, which orphaned Savings, Invest, Circles, Safe Send,\n                Activity and Take Payments behind a single page. */}\n            <NavItem icon={<LayoutDashboard size={18} />} label={t.dashboard} href=\"/\" active={pathname === '/'} onClick={() => setIsMobileMenuOpen(false)} />\n\n            <NavGroup label=\"Money\" />\n            <NavItem icon={<Wallet size={18} />} label={t.wallet} href=\"/wallet\" active={pathname === '/wallet'} onClick={() => setIsMobileMenuOpen(false)} />\n            <NavItem icon={<Send size={18} />} label={t.send} href=\"/send\" active={pathname === '/send'} onClick={() => setIsMobileMenuOpen(false)} />\n            <NavItem icon={<PiggyBank size={18} />} label={t.savings} href=\"/savings\" active={pathname === '/savings'} onClick={() => setIsMobileMenuOpen(false)} />\n            <NavItem icon={<LineChartIcon size={18} />} label={t.invest} href=\"/invest\" active={pathname === '/invest'} onClick={() => setIsMobileMenuOpen(false)} />\n            <NavItem icon={<Users size={18} />} label={t.circles} href=\"/circles\" active={pathname === '/circles'} onClick={() => setIsMobileMenuOpen(false)} />\n            <NavItem icon={<ShieldCheck size={18} />} label=\"Limits\" href=\"/limits\" active={pathname === '/limits'} onClick={() => setIsMobileMenuOpen(false)} />\n            <NavItem icon={<Gauge size={18} />} label=\"Score\" href=\"/score\" active={pathname === '/score'} onClick={() => setIsMobileMenuOpen(false)} />\n            <NavItem icon={<Receipt size={18} />} label={t.activity} href=\"/activity\" active={pathname === '/activity'} onClick={() => setIsMobileMenuOpen(false)} />\n\n            <NavGroup label=\"Paying\" />\n            <NavItem icon={<ShoppingCart size={18} />} label={t.pay} href=\"/pay\" active={pathname === '/pay'} onClick={() => setIsMobileMenuOpen(false)} />\n            <NavItem icon={<ShieldCheck size={18} />} label={t.safe} href=\"/safe\" active={pathname === '/safe'} onClick={() => setIsMobileMenuOpen(false)} />\n            <NavItem icon={<Store size={18} />} label={t.merchant} href=\"/merchant\" active={pathname === '/merchant'} onClick={() => setIsMobileMenuOpen(false)} />\n\n            <NavGroup label=\"Network\" />\n            <NavItem icon={<TrendingUp size={18} />} label={t.markets} href=\"/markets\" active={pathname === '/markets'} onClick={() => setIsMobileMenuOpen(false)} />\n            <NavItem icon={<Activity size={18} />} label=\"Ledger\" href=\"/explorer\" active={pathname === '/explorer'} onClick={() => setIsMobileMenuOpen(false)} />\n\n            {/* Only rendered for staff. am_i_staff() is the same gate the\n                admin readers use, so this cannot show a door that will not\n                open. */}\n            {isStaff && (\n              <>\n                <NavGroup label=\"Staff\" />\n                <NavItem icon={<Scale size={18} />} label={t.operations} href=\"/admin\" active={pathname === '/admin'} onClick={() => setIsMobileMenuOpen(false)} />\n              </>\n            )}\n          </nav>\n        </div>\n      </aside>\n\n      <div className=\"flex-1 flex flex-col relative h-full overflow-y-auto [&::-webkit-scrollbar]:hidden\">\n        <header className=\"h-16 sm:h-20 border-b border-[#1F2937] bg-[#111827]/80 backdrop-blur-xl sticky top-0 z-30 flex items-center justify-between px-4 sm:px-8 shrink-0\">\n          <div className=\"flex items-center gap-3 sm:gap-6 min-w-0\">\n            <div className=\"hidden sm:flex items-center gap-2 text-[11px] font-mono font-bold tracking-widest bg-[#1F2937]/50 px-4 py-2 rounded-full border border-[#1F2937]\"><span className=\"text-[#FDB813]\">1 KPC</span><span className=\"text-[#94A3B8]\">=</span><span className=\"text-white\">$1.00 USD</span></div>\n            <div className=\"flex items-center gap-2 text-[9px] sm:text-[10px] font-mono tracking-widest text-[#94A3B8] uppercase whitespace-nowrap\">\n              <div className={`w-2 h-2 rounded-full shadow-[0_0_8px_#10b981] ${ledgerLive === true ? 'bg-[#10B981] animate-pulse' : ledgerLive === false ? 'bg-[#EF4444]' : 'bg-[#94A3B8]'}`} />\n              <span>{ledgerLive === true ? 'Ledger live' : ledgerLive === false ? 'Ledger unreachable' : 'Checking...'}</span>\n            </div>\n          </div>\n          \n          <div className=\"flex items-center gap-2 sm:gap-4 z-10 shrink-0\">\n           <div className=\"relative\">\n              <button \n                onClick={() => setIsLangMenuOpen(!isLangMenuOpen)}\n                className=\"flex items-center gap-2 px-3 py-2 text-[#94A3B8] hover:text-white bg-[#111827] hover:bg-[#1F2937] border border-[#1F2937] rounded-lg transition-colors font-mono text-[10px] uppercase tracking-widest\"\n              >\n                <Globe size={14} />\n                <span className=\"hidden sm:inline\">\n                  {currentLang === 'en' ? 'EN' : currentLang === 'es' ? 'ES' : currentLang === 'fr' ? 'FR' : currentLang === 'pt' ? 'PT' : currentLang === 'zh' ? '中文' : '日本語'}\n                </span>\n                <ChevronDown size={14} className={`transition-transform duration-200 ${isLangMenuOpen ? 'rotate-180' : ''}`} />\n              </button>\n\n              <AnimatePresence>\n                {isLangMenuOpen && (\n                  <motion.div \n                    initial={{ opacity: 0, y: -10 }}\n                    animate={{ opacity: 1, y: 0 }}\n                    exit={{ opacity: 0, y: -10 }}\n                    className=\"absolute right-0 mt-2 w-32 bg-[#111827] border border-[#1F2937] rounded-xl shadow-[0_0_30px_rgba(0,0,0,0.8)] overflow-hidden z-50 flex flex-col\"\n                  >\n                    <button onClick={() => { setCurrentLang('en'); setIsLangMenuOpen(false); }} className={`px-4 py-3 text-left text-xs font-mono tracking-widest hover:bg-[#1F2937] transition-colors ${currentLang === 'en' ? 'text-[#FDB813]' : 'text-white'}`}>English</button>\n                    <button onClick={() => { setCurrentLang('es'); setIsLangMenuOpen(false); }} className={`px-4 py-3 text-left text-xs font-mono tracking-widest hover:bg-[#1F2937] transition-colors border-t border-[#1F2937] ${currentLang === 'es' ? 'text-[#FDB813]' : 'text-white'}`}>Español</button>\n                    <button onClick={() => { setCurrentLang('fr'); setIsLangMenuOpen(false); }} className={`px-4 py-3 text-left text-xs font-mono tracking-widest hover:bg-[#1F2937] transition-colors border-t border-[#1F2937] ${currentLang === 'fr' ? 'text-[#FDB813]' : 'text-white'}`}>Français</button>\n                    <button onClick={() => { setCurrentLang('pt'); setIsLangMenuOpen(false); }} className={`px-4 py-3 text-left text-xs font-mono tracking-widest hover:bg-[#1F2937] transition-colors border-t border-[#1F2937] ${currentLang === 'pt' ? 'text-[#FDB813]' : 'text-white'}`}>Português</button>\n                    <button onClick={() => { setCurrentLang('zh'); setIsLangMenuOpen(false); }} className={`px-4 py-3 text-left text-xs font-mono tracking-widest hover:bg-[#1F2937] transition-colors border-t border-[#1F2937] ${currentLang === 'zh' ? 'text-[#FDB813]' : 'text-white'}`}>简体中文</button>\n                    <button onClick={() => { setCurrentLang('ja'); setIsLangMenuOpen(false); }} className={`px-4 py-3 text-left text-xs font-mono tracking-widest hover:bg-[#1F2937] transition-colors border-t border-[#1F2937] ${currentLang === 'ja' ? 'text-[#FDB813]' : 'text-white'}`}>日本語</button>\n                  </motion.div>\n                )}\n              </AnimatePresence>\n            </div>\n            \n            <ConnectButton.Custom>\n              {({ account, chain, openAccountModal, openChainModal, openConnectModal, mounted }) => {\n                const ready = mounted;\n                const connected = ready && account && chain;\n                return (\n                  <div {...(!ready && { 'aria-hidden': true, style: { opacity: 0, pointerEvents: 'none', userSelect: 'none' }})}>\n                    {(() => {\n                      if (!connected) {\n                        return (\n                          <button onClick={openConnectModal} className=\"text-[9px] sm:text-[10px] font-mono font-bold tracking-[0.1em] sm:tracking-[0.2em] bg-[#FDB813] text-[#0A0E14] px-3 sm:px-6 py-2 rounded uppercase whitespace-nowrap shadow-[0_0_15px_rgba(253,184,19,0.3)] hover:bg-[#F59E0B] transition-colors\">\n                            Launch Wallet\n                          </button>\n                        );\n                      }\n                      return (\n                        <div className=\"flex gap-3\">\n                          <button onClick={openChainModal} className=\"hidden sm:flex items-center text-[10px] font-mono border border-[#1F2937] px-3 py-2 rounded text-[#94A3B8] hover:bg-[#1F2937] transition-all\">\n                            {chain.hasIcon && (\n                              <div style={{ background: chain.iconBackground, width: 14, height: 14, borderRadius: 999, overflow: 'hidden', display: 'inline-block', marginRight: 6 }}>\n                                {chain.iconUrl && (<img alt={chain.name ?? 'Chain icon'} src={chain.iconUrl} style={{ width: 14, height: 14 }} />)}\n                              </div>\n                            )}\n                            {chain.name}\n                          </button>\n                          <button onClick={openAccountModal} className=\"text-[10px] font-mono font-bold bg-[#1F2937] text-white px-4 py-2 rounded border border-[#FDB813]/30 hover:border-[#FDB813] transition-all\">\n                            {account.displayName}\n                            {account.displayBalance ? ` (${account.displayBalance})` : ''}\n                          </button>\n                        </div>\n                      );\n                    })()}\n                  </div>\n                );\n              }}\n            </ConnectButton.Custom>\n          </div>\n        </header>\n\n        <div className=\"w-full bg-[#FDB813] text-[#0A0E14] py-2 overflow-hidden flex items-center whitespace-nowrap z-20 border-b border-[#F59E0B]\">\n          <motion.div animate={{ x: [\"0%\", \"-50%\"] }} transition={{ repeat: Infinity, ease: \"linear\", duration: 30 }} className=\"flex gap-8 sm:gap-16 text-[10px] sm:text-[11px] font-mono font-black tracking-widest uppercase\">\n            {[...tickerItems, ...tickerItems].map((item, i) => <span key={i}>{item}</span>)}\n          </motion.div>\n        </div>\n\n        <main className=\"p-4 sm:p-6 lg:px-12 lg:py-10 relative z-10 flex-1\">\n          <div className=\"max-w-[1800px] mx-auto space-y-6 lg:space-y-10\">\n            \n            <div className=\"bg-[#0A0E14]/80 backdrop-blur-xl border border-[#1F2937] rounded-2xl sm:rounded-3xl p-5 sm:p-8 relative overflow-hidden group shadow-[0_0_80px_rgba(0,0,0,0.8)] max-w-4xl mt-0 sm:mt-2 flex flex-col items-center justify-center gap-4 sm:gap-5 text-center mx-auto\">\n              <div className=\"absolute top-1/2 left-1/2 w-full lg:w-[80%] h-64 -translate-y-1/2 -translate-x-1/2 bg-gradient-to-r from-[#AA771C]/20 via-[#AA771C]/5 to-transparent blur-[100px]\" />\n              <div className=\"relative z-10 inline-flex items-center gap-2 sm:gap-3 px-3 sm:px-4 py-2 border border-[#FDB813]/30 rounded-full bg-[#0A0E14]/60\"><Shield size={12} className=\"text-[#FDB813] shrink-0\" /><span className=\"text-[9px] sm:text-[10px] font-mono tracking-[0.12em] sm:tracking-[0.2em] text-[#FDB813] uppercase font-bold\">The Sovereign Payment Rail</span></div>\n              <div className=\"relative z-10 w-full max-w-xl aspect-video rounded-xl overflow-hidden border border-[#FDB813]/30 bg-black shadow-[0_0_50px_rgba(253,184,19,0.1)]\"><video src=\"/kpc-video.mp4\" autoPlay loop muted playsInline className=\"w-full h-full object-cover scale-105\" /></div>\n              <div className=\"relative z-10 flex gap-3 sm:gap-4 w-full justify-center max-w-md\">\n                <motion.button \n                  onClick={() => {\n                    if (!currentUser) {\n                      window.location.href = '/auth?redirect_uri=' + encodeURIComponent(window.location.href);\n                      return;\n                    }\n                    setIsBuyModalOpen(true);\n                  }}\n                  whileHover={{ scale: 1.03 }} \n                  whileTap={{ scale: 0.95 }} \n                  animate={{ boxShadow: [\"0px 0px 15px rgba(244, 208, 104, 0.4)\", \"0px 0px 45px rgba(255, 240, 168, 0.8)\", \"0px 0px 15px rgba(244, 208, 104, 0.4)\"] }} \n                  transition={{ duration: 2, repeat: Infinity }} \n                  className=\"relative overflow-hidden w-1/2 px-2 sm:px-6 py-3.5 sm:py-4 bg-gradient-to-r from-[#AA771C] via-[#FFF0A8] to-[#AA771C] bg-[length:200%_auto] text-[#0A0E14] rounded-lg cursor-pointer border border-[#FFF0A8]/60 font-mono font-black tracking-[0.06em] sm:tracking-[0.2em] text-[10px] sm:text-[11px] uppercase whitespace-nowrap flex items-center justify-center gap-1.5 sm:gap-2\"\n                >\n                  <motion.div className=\"absolute inset-y-0 w-1/2 bg-gradient-to-r from-transparent via-white/70 to-transparent skew-x-[-20deg]\" initial={{ left: '-100%' }} animate={{ left: '200%' }} transition={{ repeat: Infinity, duration: 2.5, ease: \"linear\", repeatDelay: 1 }} />\n                  Buy KPC <Zap size={14} className=\"animate-pulse\" />\n                </motion.button>\n                <button onClick={() => handleFeatureClick('Explorer')} className=\"w-1/2 px-2 sm:px-6 py-3.5 sm:py-4 bg-[#111827] text-[#F9FAFB] border border-[#1F2937] font-mono font-bold tracking-[0.06em] sm:tracking-[0.2em] text-[10px] sm:text-[11px] uppercase whitespace-nowrap hover:border-[#FDB813]/50 rounded-lg flex items-center justify-center transition-all\">Explore Network</button>\n              </div>\n            </div>\n\n            <div className=\"grid grid-cols-2 md:grid-cols-4 2xl:grid-cols-8 gap-3 lg:gap-4\">\n              <StatCard label=\"Live Price\" value={networkStats.price} prefix=\"$\" suffix=\" USD\" decimals={2} onClick={() => setActiveDrawer(\"live_price\")} />\n              <StatCard label=\"24h Volume\" value={networkStats.volume} prefix=\"$\" isShort onClick={() => setActiveDrawer(\"volume\")} />\n              <StatCard label=\"Market Cap\" value={networkStats.marketCap} prefix=\"$\" isShort onClick={() => setActiveDrawer(\"market_cap\")} />\n              <StatCard label=\"Txns Today\" value={networkStats.txnsToday} onClick={() => setActiveDrawer(\"txns\")} />\n              <StatCard label=\"Holders\" value={networkStats.holders} onClick={() => setActiveDrawer(\"holders\")} />\n              {/* Was \"Network LIVE/OFFLINE\", meaning a public Ethereum RPC\n                  answered. Countries is a fact about KobPay. */}\n              <StatCard label=\"Countries\" value={networkStats.countries} onClick={() => setActiveDrawer(\"global\")} />\n              {/* Was a hardcoded $0.001 of Ethereum gas. transfer_fee_bps is\n                  0, so sending really is free, and a true zero is worth more\n                  than an invented fraction. */}\n              <StatCard label=\"Send Fee\" customValue={<span className=\"text-[#10B981]\">{networkStats.transferFeeBps === 0 ? \"FREE\" : `${(networkStats.transferFeeBps / 100).toFixed(2)}%`}</span>} onClick={() => setActiveDrawer(\"fee\")} />\n              <StatCard label=\"Circulating\" value={networkStats.circulating} suffix=\"M KPC\" decimals={1} onClick={() => setActiveDrawer(\"circulating\")} />\n            </div>\n\n            <div className=\"grid grid-cols-1 lg:grid-cols-12 gap-5 lg:gap-8\">\n              <div className=\"lg:col-span-8 bg-[#111827]/80 backdrop-blur-xl border border-[#1F2937] rounded-2xl sm:rounded-[2rem] p-5 sm:p-8 lg:p-10 flex flex-col shadow-2xl\">\n                <div className=\"flex justify-between items-center mb-5 sm:mb-8\">\n                  <div><h3 className=\"text-base sm:text-xl font-black uppercase tracking-widest mb-2 flex items-center gap-2 sm:gap-3\"><Activity className=\"text-[#FDB813]\" size={20} /> Fiat Depreciation</h3><p className=\"text-[10px] font-mono text-[#94A3B8] tracking-widest uppercase\">While currencies lose value, KPC holds $1.00.</p></div>\n                </div>\n                <div className=\"h-[240px] sm:h-[300px] lg:h-[350px] w-full font-mono text-[9px] sm:text-[10px]\">\n                  <ResponsiveContainer width=\"100%\" height=\"100%\"><LineChart data={liveChartData}><CartesianGrid strokeDasharray=\"3 3\" stroke=\"#1F2937\" vertical={false} /><XAxis dataKey=\"month\" stroke=\"#94A3B8\" /><YAxis stroke=\"#94A3B8\" tickFormatter={(val: number) => `${(val * 100).toFixed(0)}%`} /><Tooltip contentStyle={{ backgroundColor: '#0A0E14', border: '1px solid #1F2937' }} /><Legend /><Line type=\"monotone\" dataKey=\"KPC\" name=\"🪙 KPC\" stroke=\"#FDB813\" strokeWidth={3} dot={false} /><Line type=\"monotone\" dataKey=\"GHS\" name=\"🇬🇭 GHS\" stroke=\"#EF4444\" strokeWidth={2} strokeOpacity={0.6} dot={false} /><Line type=\"monotone\" dataKey=\"NGN\" name=\"🇳🇬 NGN\" stroke=\"#22D3EE\" strokeWidth={2} strokeOpacity={0.6} dot={false} /></LineChart></ResponsiveContainer>\n                </div>\n              </div>\n\n              <div className=\"lg:col-span-4 bg-[#111827]/80 border border-[#1F2937] rounded-2xl sm:rounded-[2rem] p-5 sm:p-8 flex flex-col shadow-2xl overflow-hidden relative\">\n                <div className=\"absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-[#22D3EE] to-transparent opacity-50\" />\n                <h3 className=\"text-sm font-black uppercase tracking-widest flex items-center gap-3 mb-6 relative z-10\">\n                  <Globe2 className=\"text-[#22D3EE] animate-pulse\" size={16} /> Live Feed\n                  <div className=\"w-1.5 h-1.5 bg-[#22D3EE] rounded-full animate-ping ml-auto\" />\n                </h3>\n                <div className=\"flex-1 overflow-hidden relative h-[280px] sm:h-[380px]\">\n                  <div className=\"absolute inset-0 overflow-y-auto pr-2 [&::-webkit-scrollbar]:hidden\">\n                    <div className=\"space-y-4\">\n                      <AnimatePresence initial={false}>\n                        {liveTxns.map((txn, i) => (\n                          <motion.div \n                            key={txn.id}\n                            layout \n                            initial={{ opacity: 0, y: -20, scale: 0.95 }}\n                            animate={{ opacity: 1, y: 0, scale: 1, backgroundColor: [\"#1F2937\", \"#0A0E14\"] }}\n                            exit={{ opacity: 0, scale: 0.9, transition: { duration: 0.2 } }}\n                            transition={{ duration: 0.4, ease: \"easeOut\" }}\n                            className=\"p-4 bg-[#0A0E14] border border-[#1F2937] rounded-2xl flex flex-col gap-3 group hover:border-[#FDB813]/30 transition-colors\"\n                          >\n                            <div className=\"flex justify-between items-center border-b border-[#1F2937] pb-2\">\n                              <span className=\"text-[9px] font-mono text-[#FDB813] tracking-widest bg-[#FDB813]/10 px-2 py-0.5 rounded\">{txn.type}</span>\n                              <span className=\"text-[9px] font-mono text-[#10B981] animate-pulse\">{txn.time}</span>\n                            </div>\n                            <div className=\"flex justify-between items-end\">\n                              <div>\n                                <span className=\"block text-xs font-mono text-[#94A3B8] uppercase\">From: <span className=\"text-white\">{txn.from}</span></span>\n                                <span className=\"block text-xs font-mono text-[#94A3B8] uppercase\">To: <span className=\"text-white\">{txn.to}</span></span>\n                              </div>\n                              <div className=\"text-right font-black font-mono text-white text-lg\">\n                                {txn.amount.toLocaleString()} <span className=\"text-[#FDB813] text-[10px]\">KPC</span>\n                              </div>\n                            </div>\n                          </motion.div>\n                        ))}\n                      </AnimatePresence>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </div>\n\n            <div className=\"pb-8 sm:pb-12 pt-2 sm:pt-4\">\n              <div className=\"flex items-center gap-3 sm:gap-4 mb-5 sm:mb-8\"><Layers className=\"text-[#FDB813] shrink-0\" /><h2 className=\"text-xl sm:text-2xl lg:text-3xl font-black uppercase tracking-tighter italic text-white\">{t.infrastructure}</h2></div>\n              <div className=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 sm:gap-6\">\n                {/* These four counters are why this section read badly: the\n                    card claiming global reach printed 1, and the card about\n                    paying printed 0.\n\n                    \"Currencies 1\" came from currencies_supported — what you\n                    can FUND in, which is Paystack/GHS only. The card is\n                    about sending, so it now shows countries reached.\n\n                    \"Stability 100%\" was a hardcoded 100 presented as a\n                    measurement. The peg is the honest version of that claim.\n\n                    \"Merchants 0\" was true and will stay 0 until the first\n                    business signs up. A traction counter on a pre-launch\n                    page measures the wrong thing, so this shows what the\n                    product does — merchant fee capped at 1% — which is a\n                    fact from platform_settings, not a number waiting to\n                    grow. Apps stays a real count: 2 is small but true. */}\n                <WhyCard index={0} icon={<Globe2 size={24} className=\"text-[#22D3EE]\" />} title=\"Send Globally\" desc=\"Send to anyone with a phone number. No bank account needed.\" statLabel=\"Countries\" statValue={networkStats.countries} onClick={() => setActiveDrawer(\"global\")} />\n                <WhyCard index={1} icon={<Shield size={24} className=\"text-[#FDB813]\" />} title=\"Hedge Savings\" desc=\"Protect against fiat decline. KPC holds $1.00 forever.\" statLabel=\"Always worth\" statText=\"$1.00\" onClick={() => setActiveDrawer(\"hedge\")} />\n                <WhyCard index={2} icon={<TrendingUp size={24} className=\"text-[#10B981]\" />} title=\"Earn Daily\" desc=\"Generate KC rewards through engagement and use.\" statLabel=\"Live Apps\" statValue={networkStats.activeApps} onClick={() => setActiveDrawer(\"earn\")} />\n                <WhyCard index={3} icon={<ShoppingCart size={24} className=\"text-[#8B5CF6]\" />} title=\"Universal Pay\" desc=\"One currency for gaming, real estate, and more.\" statLabel={networkStats.merchants > 0 ? \"Businesses\" : \"Merchant fee\"} statValue={networkStats.merchants > 0 ? networkStats.merchants : undefined} statText={networkStats.merchants > 0 ? undefined : \"1%\"} onClick={() => setActiveDrawer(\"pay\")} />\n              </div>\n            </div>\n          </div>\n        </main>\n      </div>\n\n      <AnimatePresence>\n        {activeDrawer && activeDrawerData && (\n          <><motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className=\"fixed inset-0 bg-[#0A0E14]/70 backdrop-blur-sm z-[90]\" onClick={() => setActiveDrawer(null)} />\n          <motion.div initial={{ x: '100%' }} animate={{ x: 0 }} exit={{ x: '100%' }} transition={{ type: 'spring', damping: 25, stiffness: 200 }} className=\"fixed right-0 top-0 bottom-0 w-full sm:w-[450px] bg-[#111827] border-l border-[#1F2937] z-[100] shadow-2xl flex flex-col\">\n            <div className=\"p-5 sm:p-8 border-b border-[#1F2937] flex items-start justify-between bg-[#111827]/90 backdrop-blur-md\">\n              <div className=\"flex gap-4 items-center\"><div className={`w-12 h-12 rounded-xl flex items-center justify-center border ${activeDrawerData.bg} ${activeDrawerData.border}`}>{activeDrawerData.icon}</div><div><h3 className=\"text-xl font-black uppercase text-white\">{activeDrawerData.title}</h3><p className={`text-[10px] font-mono tracking-[0.2em] uppercase mt-1 ${activeDrawerData.color}`}>{activeDrawerData.subtitle}</p></div></div>\n              <button onClick={() => setActiveDrawer(null)} className=\"text-[#94A3B8] hover:text-white p-2 bg-[#1F2937] rounded-full\"><X size={20} /></button>\n            </div>\n            <div className=\"p-5 sm:p-8 flex-1 overflow-y-auto\"><p className=\"text-xs text-[#94A3B8] font-mono leading-relaxed uppercase tracking-widest bg-[#0A0E14] p-5 rounded-2xl border border-[#1F2937] mb-8\">{activeDrawerData.details}</p><div className=\"space-y-4\">{activeDrawerData.metrics.length > 0 && (<h4 className=\"text-[10px] font-mono text-white tracking-[0.3em] uppercase flex items-center gap-2\"><Server size={12} /> Live Metrics</h4>)}{activeDrawerData.metrics.map((m: any, i: number) => (<div key={i} className=\"bg-[#0A0E14] border border-[#1F2937] p-4 rounded-xl flex justify-between items-center group hover:border-[#FDB813]/30 transition-colors\"><span className=\"text-[9px] font-mono text-[#94A3B8] uppercase\">{m.label}</span><span className=\"text-sm font-black font-mono text-white\">{m.value}</span></div>))}</div></div>\n            <div className=\"p-5 sm:p-8 border-t border-[#1F2937] bg-[#111827]\">\n              <button onClick={handleExecuteFunction} className=\"w-full py-4 bg-[#FDB813] text-[#0A0E14] font-black font-mono text-[10px] uppercase rounded flex items-center justify-center gap-2 shadow-lg hover:bg-[#F59E0B] transition-all\">\n                Execute Function <ChevronRight size={14} />\n              </button>\n            </div>\n          </motion.div></>\n        )}\n      </AnimatePresence>\n\n      <KobBotChat />\n      {isBuyModalOpen && currentUser && (\n  <BuyKpcModal\n    accessToken={currentUser.accessToken}\n    onClose={() => setIsBuyModalOpen(false)}\n  />\n)}\n    </div>\n  );\n}\n\n// --- COMPONENTS ---\nfunction NavGroup({ label }: { label: string }) {\n  return (\n    <p className=\"px-3 lg:px-4 pt-3 lg:pt-4 pb-1 text-[9px] font-mono font-bold uppercase tracking-[0.2em] text-[#4B5563]\">\n      {label}\n    </p>\n  );\n}\n\nfunction NavItem({ icon, label, active = false, onClick, href = \"#\" }: { icon: React.ReactNode, label: string, active?: boolean, onClick?: () => void, href?: string }) {\n  return (\n    <Link \n      href={href} \n      onClick={onClick} \n      className={`w-full flex items-center gap-3 lg:gap-4 px-3 lg:px-4 py-2.5 lg:py-3 rounded-lg transition-all ${active ? 'bg-[#FDB813]/10 text-[#FDB813] border border-[#FDB813]/20' : 'text-[#94A3B8] border border-transparent hover:bg-[#1F2937] hover:text-[#F9FAFB]'}`}\n    >\n      {icon}<span className=\"text-[11px] font-mono font-bold uppercase tracking-[0.15em]\">{label}</span>\n    </Link>\n  );\n}\n\nfunction StatCard({ label, value, prefix = \"\", suffix = \"\", customValue, isShort = false, decimals = 0, onClick }: any) {\n  return (\n    <div onClick={onClick} className=\"bg-[#111827]/90 backdrop-blur-md border border-[#1F2937] p-4 lg:p-5 rounded-2xl flex flex-col justify-between group hover:border-[#FDB813]/30 hover:-translate-y-1 transition-all duration-300 shadow-lg cursor-pointer overflow-hidden\">\n      <span className=\"text-[9px] font-mono text-[#94A3B8] uppercase tracking-[0.15em] whitespace-nowrap group-hover:text-white transition-colors\">{label}</span>\n      <div className=\"text-sm md:text-base 2xl:text-xl font-black mt-2 lg:mt-3 text-white tracking-tighter group-hover:text-[#FDB813] transition-colors flex items-baseline gap-0.5\">\n        {customValue ? customValue : (<>{prefix}{isShort ? <span className=\"font-mono\">{(value / 1000000).toFixed(2)}M</span> : <RollingNum value={value} decimals={decimals} />}<span className=\"text-[8px] xl:text-[10px] text-[#FDB813] whitespace-nowrap ml-0.5\">{suffix}</span></>)}\n      </div>\n    </div>\n  );\n}\n\n// statText renders a stat that is not a count — a peg, a rate, a fee. Without\n// it every stat had to be a number, which is how \"Stability\" ended up as a\n// hardcoded 100 dressed as a measurement.\nfunction WhyCard({ index = 0, icon, title, desc, statLabel, statValue, statText, statSuffix = \"\", onClick }: any) {\n  return (\n    <div onClick={onClick} className=\"bg-[#111827] border border-[#1F2937] p-6 lg:p-8 rounded-2xl sm:rounded-[2rem] flex flex-col group hover:-translate-y-1 hover:border-[#FDB813]/30 transition-all duration-300 shadow-xl cursor-pointer relative overflow-hidden min-h-[200px] sm:min-h-[280px] h-full\">\n      <motion.div \n        animate={{ opacity: [0.03, 0.20, 0.03], y: [0, -3, 0] }}\n        transition={{ duration: 4, repeat: Infinity, ease: \"easeInOut\", delay: index * 0.6 }}\n        className=\"absolute top-6 right-6 pointer-events-none\"\n      >\n        <div className=\"scale-[1.25] text-[#94A3B8]\">\n          {icon}\n        </div>\n      </motion.div>\n      <div className=\"relative z-10 flex-1\">\n        <div className=\"w-12 h-12 rounded-2xl bg-[#1F2937] flex items-center justify-center mb-6 border border-[#1F2937]\">{icon}</div>\n        <h3 className=\"text-base xl:text-lg font-black uppercase tracking-widest mb-3 text-white\">{title}</h3>\n        <p className=\"text-[10px] font-mono text-[#94A3B8] leading-relaxed uppercase\">{desc}</p>\n      </div>\n      <div className=\"mt-auto pt-5 border-t border-[#1F2937] flex justify-between items-end relative z-10\">\n        <span className=\"text-[9px] font-mono text-[#94A3B8] uppercase\">{statLabel}</span>\n        <span className=\"text-xl xl:text-2xl font-black font-mono tracking-tighter text-white group-hover:text-[#FDB813] transition-colors\">\n          {statText ? statText : <><RollingNum value={statValue ?? 0} decimals={(statValue ?? 0) % 1 !== 0 ? 1 : 0} />{statSuffix}</>}\n        </span>\n      </div>\n    </div>\n  );\n}\n\nconst KobBotAvatar = ({ className = \"w-full h-full\" }: { className?: string }) => (\n  <svg viewBox=\"0 0 100 100\" className={className} xmlns=\"http://www.w3.org/2000/svg\">\n    <defs>\n      <linearGradient id=\"gold-grad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n        <stop offset=\"0%\" stopColor=\"#FFF0A8\" />\n        <stop offset=\"50%\" stopColor=\"#FDB813\" />\n        <stop offset=\"100%\" stopColor=\"#AA771C\" />\n      </linearGradient>\n      <linearGradient id=\"bg-grad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n        <stop offset=\"0%\" stopColor=\"#1F2937\" />\n        <stop offset=\"100%\" stopColor=\"#0A0E14\" />\n      </linearGradient>\n      <filter id=\"glow\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n        <feGaussianBlur stdDeviation=\"2\" result=\"blur\" />\n        <feComposite in=\"SourceGraphic\" in2=\"blur\" operator=\"over\" />\n      </filter>\n    </defs>\n    <circle cx=\"50\" cy=\"50\" r=\"48\" fill=\"url(#bg-grad)\" stroke=\"url(#gold-grad)\" strokeWidth=\"2\" />\n    <circle cx=\"50\" cy=\"50\" r=\"42\" fill=\"none\" stroke=\"#FDB813\" strokeWidth=\"0.5\" strokeDasharray=\"4 2\" opacity=\"0.4\"/>\n    <path d=\"M 50 12 L 50 25 L 35 25 L 35 35\" fill=\"none\" stroke=\"url(#gold-grad)\" strokeWidth=\"1\" />\n    <circle cx=\"50\" cy=\"12\" r=\"1.5\" fill=\"#FDB813\" />\n    <circle cx=\"35\" cy=\"35\" r=\"1.5\" fill=\"#FDB813\" />\n    <path d=\"M 50 12 L 50 25 L 65 25 L 65 35\" fill=\"none\" stroke=\"url(#gold-grad)\" strokeWidth=\"1\" />\n    <circle cx=\"65\" cy=\"35\" r=\"1.5\" fill=\"#FDB813\" />\n    <path d=\"M 15 50 L 25 50 L 25 65 L 35 65\" fill=\"none\" stroke=\"url(#gold-grad)\" strokeWidth=\"1\" opacity=\"0.7\"/>\n    <circle cx=\"15\" cy=\"50\" r=\"1.5\" fill=\"#FDB813\" />\n    <path d=\"M 85 50 L 75 50 L 75 65 L 65 65\" fill=\"none\" stroke=\"url(#gold-grad)\" strokeWidth=\"1\" opacity=\"0.7\"/>\n    <circle cx=\"85\" cy=\"50\" r=\"1.5\" fill=\"#FDB813\" />\n    <path d=\"M 38 32 L 38 68 L 44 68 L 44 52 L 55 68 L 64 68 L 49 48 L 64 32 L 55 32 L 44 45 L 44 32 Z\" fill=\"url(#gold-grad)\" filter=\"url(#glow)\"/>\n    <rect x=\"33\" y=\"46\" width=\"4\" height=\"2\" fill=\"#FFF\" filter=\"url(#glow)\" />\n    <rect x=\"63\" y=\"46\" width=\"4\" height=\"2\" fill=\"#FFF\" filter=\"url(#glow)\" />\n    <path d=\"M 40 76 L 60 76 L 56 82 L 44 82 Z\" fill=\"url(#gold-grad)\" />\n  </svg>\n);\n\nfunction KobBotChat() {\n  const [isOpen, setIsOpen] = useState(false);\n  const [messages, setMessages] = useState<{role: string, content: string}[]>([{ role: 'model', content: \"System online. I am KobBot 2.0. How can I assist you with the Sovereign Rail today?\" }]);\n  const [input, setInput] = useState(\"\");\n  const [isLoading, setIsLoading] = useState(false);\n  const messagesEndRef = useRef<HTMLDivElement>(null);\n\n  const scrollToBottom = () => {\n    messagesEndRef.current?.scrollIntoView({ behavior: \"smooth\" });\n  };\n\n  useEffect(() => {\n    scrollToBottom();\n  }, [messages]);\n\n  const handleSend = async () => {\n    if (!input.trim()) return;\n    const userText = input;\n    setInput(\"\");\n    \n    const newMessages = [...messages, { role: 'user', content: userText }];\n    setMessages(newMessages);\n    setIsLoading(true);\n\n    try {\n      const response = await fetch('/api/chat', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          prompt: userText,\n          history: messages.map(m => ({ role: m.role, parts: [{ text: m.content }] }))\n        }),\n      });\n\n      const data = await response.json();\n      if (data.error) throw new Error(data.error);\n\n      setMessages(prev => [...prev, { role: 'model', content: data.text }]);\n    } catch (error) {\n      console.error(error);\n      toast.error(\"KobBot connection lost.\");\n      setMessages(prev => [...prev, { role: 'model', content: \"[SYSTEM ERROR] Connection to AI Core failed.\" }]);\n    } finally {\n      setIsLoading(false);\n    }\n  };\n\n  return (\n    <>\n      <motion.button \n        onClick={() => setIsOpen(!isOpen)}\n        whileHover={{ scale: 1.05 }}\n        whileTap={{ scale: 0.95 }}\n        className=\"fixed bottom-8 right-8 w-14 h-14 bg-gradient-to-br from-[#111827] to-[#0A0E14] rounded-full shadow-[0_0_20px_rgba(253,184,19,0.3)] flex items-center justify-center z-[100] overflow-hidden border border-[#FDB813]/30\"\n      >\n        {isOpen ? <X size={24} className=\"text-[#FDB813]\" /> : <KobBotAvatar className=\"w-12 h-12 drop-shadow-[0_0_10px_rgba(253,184,19,0.5)]\" />}\n      </motion.button>\n\n      <AnimatePresence>\n        {isOpen && (\n          <motion.div \n            initial={{ opacity: 0, y: 20, scale: 0.95 }}\n            animate={{ opacity: 1, y: 0, scale: 1 }}\n            exit={{ opacity: 0, y: 20, scale: 0.95 }}\n            transition={{ duration: 0.2 }}\n          className=\"fixed bottom-28 right-8 w-[350px] h-[500px] max-h-[calc(100vh-140px)] bg-[#111827]/95 backdrop-blur-xl border border-[#1F2937] rounded-2xl shadow-[0_0_40px_rgba(0,0,0,0.8)] z-[100] flex flex-col overflow-hidden\"\n          >\n            <div className=\"p-4 border-b border-[#1F2937] bg-[#0A0E14]/50 flex items-center justify-between\">\n              <div className=\"flex items-center gap-3\">\n                <div className=\"w-8 h-8 rounded-full bg-[#0A0E14] border border-[#374151] flex items-center justify-center overflow-hidden shrink-0 shadow-[0_0_10px_rgba(253,184,19,0.2)]\">\n                  <KobBotAvatar className=\"w-full h-full scale-110\" />\n                </div>\n                <div>\n                  <div className=\"font-mono font-bold text-white tracking-widest text-xs uppercase flex items-center gap-2\">\n                    KobBot 2.0 <div className=\"w-1.5 h-1.5 bg-[#10B981] rounded-full animate-pulse shadow-[0_0_8px_#10b981]\" />\n                  </div>\n                  <div className=\"text-[9px] font-mono text-[#94A3B8] tracking-widest uppercase mt-0.5\">Sovereign AI Core</div>\n                </div>\n              </div>\n            </div>\n\n            <div className=\"flex-1 overflow-y-auto p-4 space-y-4 [&::-webkit-scrollbar]:hidden\">\n              {messages.map((msg, i) => (\n                <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>\n                  <div className={`max-w-[80%] p-3 rounded-xl text-xs font-mono leading-relaxed ${\n                    msg.role === 'user' \n                      ? 'bg-[#FDB813]/20 text-[#FDB813] border border-[#FDB813]/30 rounded-br-none' \n                      : 'bg-[#1F2937] text-white border border-[#374151] rounded-bl-none'\n                  }`}>\n                    {msg.content}\n                  </div>\n                </div>\n              ))}\n              {isLoading && (\n                <div className=\"flex justify-start\">\n                  <div className=\"bg-[#1F2937] text-[#94A3B8] p-3 rounded-xl rounded-bl-none border border-[#374151] flex items-center gap-2\">\n                    <Loader2 size={14} className=\"animate-spin\" /> <span className=\"text-[10px] font-mono tracking-widest uppercase\">Processing...</span>\n                  </div>\n                </div>\n              )}\n              <div ref={messagesEndRef} />\n            </div>\n\n            <div className=\"p-4 border-t border-[#1F2937] bg-[#0A0E14]/50 flex gap-2\">\n              <input \n                type=\"text\" \n                value={input}\n                onChange={(e) => setInput(e.target.value)}\n                onKeyDown={(e) => e.key === 'Enter' && handleSend()}\n                placeholder=\"Query network data...\"\n                className=\"flex-1 bg-[#111827] border border-[#374151] rounded-lg px-4 py-2 text-xs font-mono text-white outline-none focus:border-[#FDB813]/50 transition-colors\"\n              />\n              <button \n                onClick={handleSend}\n                disabled={isLoading || !input.trim()}\n                className=\"bg-[#FDB813] text-[#0A0E14] p-2 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed hover:bg-[#F59E0B] transition-colors flex items-center justify-center w-10\"\n              >\n                <Send size={16} />\n              </button>\n            </div>\n          </motion.div>\n        )}\n      </AnimatePresence>\n    </>\n  );\n}", true);

